import type { BankQuestion } from "@/lib/bank";

/** Algebra, Geometry and Trigonometry (SSC) (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-algebra-geometry-1","question":"If x + 1/x = 3, then x² + 1/x² equals:","options":["7","11","5","9"],"answer":0,"explanation":"Square both sides: x² + 2 + 1/x² = 9, so x² + 1/x² = 9 − 2 = 7. Choosing 11 means adding the cross term 2 instead of subtracting it; 9 forgets it altogether.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि x + 1/x = 3 है, तो x² + 1/x² बराबर है:","optionsHi":["7","11","5","9"],"explanationHi":"दोनों पक्षों का वर्ग करने पर: x² + 2 + 1/x² = 9, अतः x² + 1/x² = 9 − 2 = 7। 11 चुनने का अर्थ है 2 को घटाने के बजाय जोड़ देना; 9 में इसे पूरी तरह छोड़ दिया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-2","question":"The value of sin 30° + cos 60° is:","options":["1","√3","1/2","√3/2"],"answer":0,"explanation":"sin 30° = 1/2 and cos 60° = 1/2 (complementary angles), so the sum is exactly 1. Picking 1/2 counts only one term, and √3/2 mixes up sin 30° with sin 60°.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"sin 30° + cos 60° का मान है:","optionsHi":["1","√3","1/2","√3/2"],"explanationHi":"sin 30° = 1/2 और cos 60° = 1/2 (पूरक कोण), अतः योगफल ठीक 1 है। 1/2 चुनने पर केवल एक पद गिना गया है, और √3/2 में sin 30° को sin 60° समझ लिया गया है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-3","question":"The sum of the interior angles of a hexagon is:","options":["720°","540°","360°","900°"],"answer":0,"explanation":"Interior angle sum = (n − 2) × 180° = 4 × 180° = 720° for n = 6. 540° is the pentagon's sum, and 360° is the exterior-angle total for any polygon, a common mix-up.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"षट्भुज के आंतरिक कोणों का योग है:","optionsHi":["720°","540°","360°","900°"],"explanationHi":"आंतरिक कोणों का योग = (n − 2) × 180° = 4 × 180° = 720° (n = 6 के लिए)। 540° पंचभुज का योग है, और 360° किसी भी बहुभुज के बाह्य कोणों का योग है, जो एक आम भ्रम है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-4","question":"If a + b = 5 and ab = 6, then a² + b² equals:","options":["11","25","19","13"],"answer":3,"explanation":"Use a² + b² = (a + b)² − 2ab = 25 − 12 = 13 (a and b are 2 and 3). Picking 25 forgets the −2ab term, and 19 subtracts ab only once.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि a + b = 5 और ab = 6 है, तो a² + b² बराबर है:","optionsHi":["11","25","19","13"],"explanationHi":"a² + b² = (a + b)² − 2ab = 25 − 12 = 13 (a और b क्रमशः 2 और 3 हैं)। 25 चुनने पर −2ab पद छूट गया है, और 19 में ab को केवल एक बार घटाया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-5","question":"If x + 1/x = 4, then x³ + 1/x³ equals:","options":["60","64","76","52"],"answer":3,"explanation":"Use x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 64 − 12 = 52. Answering 64 drops the correction term, and 76 adds 12 instead of subtracting it.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि x + 1/x = 4 है, तो x³ + 1/x³ बराबर है:","optionsHi":["60","64","76","52"],"explanationHi":"x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 64 − 12 = 52। उत्तर 64 में सुधार वाला पद छोड़ दिया गया है, और 76 में 12 को घटाने के बजाय जोड़ दिया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-6","question":"If a + b = 10 and ab = 21, then a³ + b³ equals:","options":["1000","430","370","340"],"answer":2,"explanation":"a³ + b³ = (a + b)³ − 3ab(a + b) = 1000 − 3 × 21 × 10 = 370 (a, b are 3 and 7: 27 + 343). Writing 1000 forgets the 3ab(a + b) term entirely.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि a + b = 10 और ab = 21 है, तो a³ + b³ बराबर है:","optionsHi":["1000","430","370","340"],"explanationHi":"a³ + b³ = (a + b)³ − 3ab(a + b) = 1000 − 3 × 21 × 10 = 370 (a, b क्रमशः 3 और 7 हैं: 27 + 343)। 1000 लिखने पर 3ab(a + b) वाला पद पूरी तरह छूट गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-7","question":"The centroid of a triangle divides each median, measured from the vertex, in the ratio:","options":["1 : 2","3 : 1","1 : 1","2 : 1"],"answer":3,"explanation":"The centroid is two-thirds of the way along each median from the vertex, so the ratio from the vertex is 2 : 1.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"त्रिभुज का centroid (केंद्रक) प्रत्येक माध्यिका को शीर्ष से मापने पर किस अनुपात में बाँटता है?","optionsHi":["1 : 2","3 : 1","1 : 1","2 : 1"],"explanationHi":"केंद्रक प्रत्येक माध्यिका पर शीर्ष से दो-तिहाई दूरी पर होता है, इसलिए शीर्ष से अनुपात 2 : 1 है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-8","question":"An arc of a circle subtends 110° at the centre. What angle does it subtend at a point on the remaining part of the circle?","options":["70°","125°","55°","110°"],"answer":2,"explanation":"The angle at the circumference is half the central angle on the same arc: 110°/2 = 55°. 125° would be the angle from a point on the minor arc itself.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी वृत्त का एक चाप केंद्र पर 110° का कोण बनाता है। वृत्त के शेष भाग पर स्थित किसी बिंदु पर यह चाप कितना कोण बनाएगा?","optionsHi":["70°","125°","55°","110°"],"explanationHi":"परिधि पर बना कोण उसी चाप द्वारा केंद्र पर बने कोण का आधा होता है: 110°/2 = 55°। 125° वह कोण होगा जो लघु चाप पर स्थित बिंदु से बनता है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-9","question":"The value of tan 45° + sec 60° − cosec 30° is:","options":["1","2","0","3"],"answer":0,"explanation":"tan 45° = 1, sec 60° = 2 and cosec 30° = 2, so the value is 1 + 2 − 2 = 1.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"tan 45° + sec 60° − cosec 30° का मान है:","optionsHi":["1","2","0","3"],"explanationHi":"tan 45° = 1, sec 60° = 2 और cosec 30° = 2, अतः मान 1 + 2 − 2 = 1 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-10","question":"The angle of elevation of the top of a 50 m tall tower from a point on the ground is 30°. How far is the point from the foot of the tower?","options":["25√3 m","100 m","50/√3 m","50√3 m"],"answer":3,"explanation":"tan 30° = height/distance, so d = 50/tan 30° = 50√3 ≈ 86.6 m. The tempting 50/√3 m comes from multiplying by tan 30° instead of dividing, i.e. treating 50 m as the base.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"जमीन पर स्थित किसी बिंदु से 50 m ऊँची मीनार के शीर्ष का उन्नयन कोण 30° है। वह बिंदु मीनार के आधार से कितनी दूर है?","optionsHi":["25√3 m","100 m","50/√3 m","50√3 m"],"explanationHi":"tan 30° = ऊँचाई/दूरी, अतः d = 50/tan 30° = 50√3 ≈ 86.6 m। भ्रामक उत्तर 50/√3 m तब आता है जब भाग देने के बजाय tan 30° से गुणा कर दिया जाए, यानी 50 m को आधार मान लिया जाए।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-11","question":"In triangle ABC, ∠A = 70° and the bisectors of ∠B and ∠C meet at the incentre I. What is ∠BIC?","options":["135°","125°","110°","145°"],"answer":1,"explanation":"For the incentre, ∠BIC = 90° + ∠A/2 = 90° + 35° = 125°. 110° (= 180° − 70°) is ∠B + ∠C, not the angle at I, and 145° wrongly adds the full ∠A to 75°.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"त्रिभुज ABC में ∠A = 70° है और ∠B तथा ∠C के समद्विभाजक अंतःकेंद्र I पर मिलते हैं। ∠BIC कितना है?","optionsHi":["135°","125°","110°","145°"],"explanationHi":"अंतःकेंद्र के लिए ∠BIC = 90° + ∠A/2 = 90° + 35° = 125°। 110° (= 180° − 70°) ∠B + ∠C है, I पर बना कोण नहीं, और 145° में पूरे ∠A को गलती से 75° में जोड़ दिया गया है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-12","question":"If 2x + 3y = 12 and xy = 6, then 4x² + 9y² equals:","options":["144","36","72","108"],"answer":2,"explanation":"(2x + 3y)² = 4x² + 9y² + 12xy, so 4x² + 9y² = 144 − 12 × 6 = 72. 108 comes from subtracting only 6xy, forgetting the factor 2 × 2 × 3 = 12 in the cross term.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि 2x + 3y = 12 और xy = 6 है, तो 4x² + 9y² बराबर है:","optionsHi":["144","36","72","108"],"explanationHi":"(2x + 3y)² = 4x² + 9y² + 12xy, अतः 4x² + 9y² = 144 − 12 × 6 = 72। 108 में केवल 6xy घटाया गया है, यानी क्रॉस पद में गुणक 2 × 2 × 3 = 12 को भूल गए।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-13","question":"If x − 1/x = 3, then x⁴ + 1/x⁴ equals:","options":["119","121","123","79"],"answer":0,"explanation":"Since x − 1/x = 3, x² + 1/x² = 3² + 2 = 11 (plus 2 for a difference), then x⁴ + 1/x⁴ = 11² − 2 = 119. 121 forgets the −2 at the second step, and 79 wrongly uses 9 − 2 = 7 at the first step.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x − 1/x = 3 है, तो x⁴ + 1/x⁴ बराबर है:","optionsHi":["119","121","123","79"],"explanationHi":"चूँकि x − 1/x = 3, इसलिए x² + 1/x² = 3² + 2 = 11 (अंतर के लिए 2 जोड़ा जाता है), फिर x⁴ + 1/x⁴ = 11² − 2 = 119। 121 में दूसरे चरण में −2 छूट गया है, और 79 में पहले चरण में गलती से 9 − 2 = 7 लिया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-14","question":"If a + b + c = 9 and ab + bc + ca = 26, then a² + b² + c² equals:","options":["29","107","55","26"],"answer":0,"explanation":"a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81 − 52 = 29.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि a + b + c = 9 और ab + bc + ca = 26 है, तो a² + b² + c² बराबर है:","optionsHi":["29","107","55","26"],"explanationHi":"a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81 − 52 = 29।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-15","question":"If a = 23, b = 24 and c = −47, then a³ + b³ + c³ equals:","options":["77,832","−25,944","0","−77,832"],"answer":3,"explanation":"a + b + c = 0, so a³ + b³ + c³ = 3abc = 3 × 23 × 24 × (−47) = −77,832.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि a = 23, b = 24 और c = −47 है, तो a³ + b³ + c³ बराबर है:","optionsHi":["77,832","−25,944","0","−77,832"],"explanationHi":"a + b + c = 0, अतः a³ + b³ + c³ = 3abc = 3 × 23 × 24 × (−47) = −77,832।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-16","question":"H is the orthocentre of triangle ABC. If ∠A = 65°, then ∠BHC equals:","options":["122.5°","115°","130°","65°"],"answer":1,"explanation":"For an acute triangle, ∠BHC = 180° − ∠A = 115°. 130° is the circumcentre result (2A) and 122.5° the incentre result (90° + A/2).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"H त्रिभुज ABC का लंबकेंद्र है। यदि ∠A = 65° है, तो ∠BHC बराबर है:","optionsHi":["122.5°","115°","130°","65°"],"explanationHi":"न्यूनकोण त्रिभुज में ∠BHC = 180° − ∠A = 115°। 130° परिकेंद्र का परिणाम (2A) है और 122.5° अंतःकेंद्र का परिणाम (90° + A/2) है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-17","question":"O is the circumcentre of an acute triangle ABC and ∠OBC = 25°. What is ∠BAC?","options":["65°","50°","115°","130°"],"answer":0,"explanation":"OB = OC, so ∠OCB = 25° and ∠BOC = 130°. The angle at A is half the central angle: 65°.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"O न्यूनकोण त्रिभुज ABC का परिकेंद्र है और ∠OBC = 25° है। ∠BAC कितना है?","optionsHi":["65°","50°","115°","130°"],"explanationHi":"OB = OC, अतः ∠OCB = 25° और ∠BOC = 130°। A पर बना कोण केंद्रीय कोण का आधा है: 65°।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-18","question":"PA and PB are tangents from an external point P to a circle with centre O. If ∠APB = 50°, what is ∠OAB?","options":["40°","65°","50°","25°"],"answer":3,"explanation":"∠AOB = 180° − 50° = 130° (OAPB has two right angles). Triangle OAB is isosceles, so ∠OAB = (180° − 130°)/2 = 25°.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"PA और PB बाह्य बिंदु P से केंद्र O वाले वृत्त पर खींची गई स्पर्श रेखाएँ हैं। यदि ∠APB = 50° है, तो ∠OAB कितना है?","optionsHi":["40°","65°","50°","25°"],"explanationHi":"∠AOB = 180° − 50° = 130° (OAPB में दो समकोण हैं)। त्रिभुज OAB समद्विबाहु है, अतः ∠OAB = (180° − 130°)/2 = 25°।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-19","question":"If sin θ + cos θ = √2 cos θ, then cot θ equals:","options":["1/√2","√2 − 1","√2","√2 + 1"],"answer":3,"explanation":"sin θ = (√2 − 1) cos θ, so tan θ = √2 − 1 and cot θ = 1/(√2 − 1) = √2 + 1.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि sin θ + cos θ = √2 cos θ है, तो cot θ बराबर है:","optionsHi":["1/√2","√2 − 1","√2","√2 + 1"],"explanationHi":"sin θ = (√2 − 1) cos θ, अतः tan θ = √2 − 1 और cot θ = 1/(√2 − 1) = √2 + 1।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-20","question":"If sec θ + tan θ = 3, then sec θ equals:","options":["5/4","4/3","3/5","5/3"],"answer":3,"explanation":"Since sec²θ − tan²θ = 1, sec θ − tan θ = 1/3. Adding: 2 sec θ = 10/3, so sec θ = 5/3 (and tan θ = 4/3).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि sec θ + tan θ = 3 है, तो sec θ बराबर है:","optionsHi":["5/4","4/3","3/5","5/3"],"explanationHi":"चूँकि sec²θ − tan²θ = 1, इसलिए sec θ − tan θ = 1/3। जोड़ने पर: 2 sec θ = 10/3, अतः sec θ = 5/3 (और tan θ = 4/3)।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-21","question":"From the top of a 60 m tall building, the angles of depression of the top and the foot of a tower are 30° and 60°. What is the height of the tower?","options":["40 m","45 m","20 m","30 m"],"answer":0,"explanation":"Distance = 60/tan 60° = 20√3 m. The drop to the tower’s top = 20√3 × tan 30° = 20 m, so the tower is 60 − 20 = 40 m.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"60 m ऊँची इमारत के शीर्ष से एक मीनार के शीर्ष और आधार के अवनमन कोण क्रमशः 30° और 60° हैं। मीनार की ऊँचाई कितनी है?","optionsHi":["40 m","45 m","20 m","30 m"],"explanationHi":"दूरी = 60/tan 60° = 20√3 m। मीनार के शीर्ष तक की गिरावट = 20√3 × tan 30° = 20 m, अतः मीनार की ऊँचाई 60 − 20 = 40 m है।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-22","question":"In triangle ABC, DE ∥ BC with D on AB and E on AC, and AD : DB = 2 : 3. What is the ratio of the area of triangle ADE to the area of trapezium DBCE?","options":["4 : 9","4 : 21","2 : 3","4 : 25"],"answer":1,"explanation":"AD : AB = 2 : 5, so the areas of ADE and ABC are 4 : 25 and the trapezium is 25 − 4 = 21 parts: 4 : 21.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"त्रिभुज ABC में DE ∥ BC है, जहाँ D भुजा AB पर और E भुजा AC पर है, तथा AD : DB = 2 : 3 है। त्रिभुज ADE और समलंब चतुर्भुज DBCE के क्षेत्रफलों का अनुपात क्या है?","optionsHi":["4 : 9","4 : 21","2 : 3","4 : 25"],"explanationHi":"AD : AB = 2 : 5, अतः ADE और ABC के क्षेत्रफल 4 : 25 के अनुपात में हैं और समलंब चतुर्भुज 25 − 4 = 21 भाग है: 4 : 21।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-23","question":"If x = √3 + √2, then x² + 1/x² equals:","options":["12","10","8","14"],"answer":1,"explanation":"1/x = √3 − √2, so x + 1/x = 2√3 and x² + 1/x² = 12 − 2 = 10.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x = √3 + √2 है, तो x² + 1/x² बराबर है:","optionsHi":["12","10","8","14"],"explanationHi":"1/x = √3 − √2, अतः x + 1/x = 2√3 और x² + 1/x² = 12 − 2 = 10।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-24","question":"ABCD is a cyclic quadrilateral with ∠A = (2x + 10)° and ∠C = (3x − 5)°. What is ∠A?","options":["80°","100°","90°","70°"],"answer":0,"explanation":"Opposite angles of a cyclic quadrilateral add up to 180°: 5x + 5 = 180, x = 35, so ∠A = 80° (and ∠C = 100°).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"ABCD एक चक्रीय चतुर्भुज है जिसमें ∠A = (2x + 10)° और ∠C = (3x − 5)° है। ∠A कितना है?","optionsHi":["80°","100°","90°","70°"],"explanationHi":"चक्रीय चतुर्भुज के सम्मुख कोणों का योग 180° होता है: 5x + 5 = 180, x = 35, अतः ∠A = 80° (और ∠C = 100°)।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-25","question":"If x + 1/x = √5, then x⁵ + 1/x⁵ equals:","options":["6√5","3√5","4√5","5√5"],"answer":3,"explanation":"x² + 1/x² = 3 and x³ + 1/x³ = 5√5 − 3√5 = 2√5. Then x⁵ + 1/x⁵ = (x² + 1/x²)(x³ + 1/x³) − (x + 1/x) = 6√5 − √5 = 5√5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x + 1/x = √5 है, तो x⁵ + 1/x⁵ बराबर है:","optionsHi":["6√5","3√5","4√5","5√5"],"explanationHi":"x² + 1/x² = 3 और x³ + 1/x³ = 5√5 − 3√5 = 2√5। तब x⁵ + 1/x⁵ = (x² + 1/x²)(x³ + 1/x³) − (x + 1/x) = 6√5 − √5 = 5√5।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-26","question":"If a² + b² + c² − ab − bc − ca = 0 and a + b + c = 12, then a³ + b³ + c³ equals:","options":["216","64","192","144"],"answer":2,"explanation":"The condition equals ½[(a − b)² + (b − c)² + (c − a)²] = 0, so a = b = c = 4 and a³ + b³ + c³ = 3 × 64 = 192.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि a² + b² + c² − ab − bc − ca = 0 और a + b + c = 12 है, तो a³ + b³ + c³ बराबर है:","optionsHi":["216","64","192","144"],"explanationHi":"यह शर्त ½[(a − b)² + (b − c)² + (c − a)²] = 0 के बराबर है, अतः a = b = c = 4 और a³ + b³ + c³ = 3 × 64 = 192।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-27","question":"If x = 2 + √3, then x⁴ + 1/x⁴ equals:","options":["198","196","192","194"],"answer":3,"explanation":"1/x = 2 − √3, so x + 1/x = 4, x² + 1/x² = 14 and x⁴ + 1/x⁴ = 196 − 2 = 194.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x = 2 + √3 है, तो x⁴ + 1/x⁴ बराबर है:","optionsHi":["198","196","192","194"],"explanationHi":"1/x = 2 − √3, अतः x + 1/x = 4, x² + 1/x² = 14 और x⁴ + 1/x⁴ = 196 − 2 = 194।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-28","question":"If a − b = 4 and a³ − b³ = 208, then a² + b² equals:","options":["52","28","12","40"],"answer":3,"explanation":"a³ − b³ = (a − b)³ + 3ab(a − b): 208 = 64 + 12ab, so ab = 12. Then a² + b² = (a − b)² + 2ab = 16 + 24 = 40.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि a − b = 4 और a³ − b³ = 208 है, तो a² + b² बराबर है:","optionsHi":["52","28","12","40"],"explanationHi":"a³ − b³ = (a − b)³ + 3ab(a − b): 208 = 64 + 12ab, अतः ab = 12। तब a² + b² = (a − b)² + 2ab = 16 + 24 = 40।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-29","question":"How many of these statements are correct? I. The incentre always lies inside the triangle. II. The orthocentre of a right-angled triangle is the vertex of the right angle. III. The circumcentre of an obtuse-angled triangle lies outside it. IV. The centroid, circumcentre and orthocentre of a triangle are collinear.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the incentre is always inside, a right triangle's altitudes meet at the right-angle vertex, an obtuse triangle's circumcentre lies outside it beyond the longest side, and the centroid, circumcentre and orthocentre lie on the Euler line.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कितने कथन सही हैं? I. अंतःकेंद्र सदैव त्रिभुज के अंदर होता है। II. समकोण त्रिभुज का लंबकेंद्र समकोण वाला शीर्ष होता है। III. अधिक कोण त्रिभुज का परिकेंद्र उसके बाहर स्थित होता है। IV. किसी त्रिभुज का केंद्रक, परिकेंद्र और लंबकेंद्र एक ही सरल रेखा पर होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों कथन सही हैं: अंतःकेंद्र सदैव अंदर होता है, समकोण त्रिभुज के लंब समकोण वाले शीर्ष पर मिलते हैं, अधिक कोण त्रिभुज का परिकेंद्र सबसे लंबी भुजा के परे उसके बाहर होता है, और केंद्रक, परिकेंद्र तथा लंबकेंद्र यूलर रेखा पर स्थित होते हैं।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-30","question":"The angle of elevation of the top of a tower from a point A on the ground is 30°. After walking 40 m towards the tower, the angle becomes 60°. What is the height of the tower?","options":["20 m","40 m","20√3 m","40√3 m"],"answer":2,"explanation":"If x is the final distance, h = x√3 and h = (x + 40)/√3, so 3x = x + 40 and x = 20. Then h = 20√3 m ≈ 34.6 m.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"जमीन पर बिंदु A से किसी मीनार के शीर्ष का उन्नयन कोण 30° है। मीनार की ओर 40 m चलने के बाद यह कोण 60° हो जाता है। मीनार की ऊँचाई कितनी है?","optionsHi":["20 m","40 m","20√3 m","40√3 m"],"explanationHi":"यदि x अंतिम दूरी है, तो h = x√3 और h = (x + 40)/√3, अतः 3x = x + 40 और x = 20। तब h = 20√3 m ≈ 34.6 m।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-31","question":"If tan θ + cot θ = 2, then tan¹⁰⁰θ + cot¹⁰⁰θ equals:","options":["0","2","2¹⁰⁰","1"],"answer":1,"explanation":"t + 1/t = 2 means (t − 1)² = 0, so tan θ = 1 = cot θ and the sum is 1 + 1 = 2.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि tan θ + cot θ = 2 है, तो tan¹⁰⁰θ + cot¹⁰⁰θ बराबर है:","optionsHi":["0","2","2¹⁰⁰","1"],"explanationHi":"t + 1/t = 2 का अर्थ है (t − 1)² = 0, अतः tan θ = 1 = cot θ और योगफल 1 + 1 = 2 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-32","question":"If sin A + sin²A = 1, then cos²A + cos⁴A equals:","options":["1/2","0","2","1"],"answer":3,"explanation":"sin A = 1 − sin²A = cos²A, so cos²A + cos⁴A = sin A + sin²A = 1.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि sin A + sin²A = 1 है, तो cos²A + cos⁴A बराबर है:","optionsHi":["1/2","0","2","1"],"explanationHi":"sin A = 1 − sin²A = cos²A, अतः cos²A + cos⁴A = sin A + sin²A = 1।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-33","question":"In triangle ABC, right-angled at B, AB = 6 cm and BC = 8 cm. What is the distance between its centroid and its circumcentre?","options":["2 cm","5 cm","10/3 cm","5/3 cm"],"answer":3,"explanation":"AC = 10 and the circumcentre M is the midpoint of AC, with BM = 5. The centroid lies on BM two-thirds of the way from B, so GM = 5/3 cm.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"त्रिभुज ABC, B पर समकोण है, AB = 6 cm और BC = 8 cm है। इसके केंद्रक और परिकेंद्र के बीच की दूरी कितनी है?","optionsHi":["2 cm","5 cm","10/3 cm","5/3 cm"],"explanationHi":"AC = 10 और परिकेंद्र M, AC का मध्य बिंदु है, जिसमें BM = 5। केंद्रक BM पर B से दो-तिहाई दूरी पर स्थित है, अतः GM = 5/3 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-34","question":"Two parallel chords of a circle of radius 10 cm are 16 cm and 12 cm long and lie on opposite sides of the centre. What is the distance between them?","options":["10 cm","12 cm","2 cm","14 cm"],"answer":3,"explanation":"Distances from the centre: √(100 − 64) = 6 and √(100 − 36) = 8. On opposite sides they add: 14 cm (2 cm if on the same side).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"10 cm त्रिज्या वाले एक वृत्त की दो समांतर जीवाएँ 16 cm और 12 cm लंबी हैं और केंद्र के विपरीत ओर स्थित हैं। उनके बीच की दूरी कितनी है?","optionsHi":["10 cm","12 cm","2 cm","14 cm"],"explanationHi":"केंद्र से दूरियाँ: √(100 − 64) = 6 और √(100 − 36) = 8। विपरीत ओर होने पर ये जुड़ती हैं: 14 cm (एक ही ओर होने पर 2 cm)।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-35","question":"The minimum value of 9 tan²θ + 4 cot²θ is:","options":["6","36","13","12"],"answer":3,"explanation":"By AM ≥ GM, 9 tan²θ + 4 cot²θ ≥ 2√(9 × 4) = 12, reached when tan²θ = 2/3.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"9 tan²θ + 4 cot²θ का न्यूनतम मान है:","optionsHi":["6","36","13","12"],"explanationHi":"AM ≥ GM से, 9 tan²θ + 4 cot²θ ≥ 2√(9 × 4) = 12, जो tan²θ = 2/3 पर प्राप्त होता है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-36","question":"If x² − 3x + 1 = 0, then x⁶ + 1/x⁶ equals:","options":["324","322","318","326"],"answer":1,"explanation":"Dividing by x: x + 1/x = 3. Then x³ + 1/x³ = 27 − 9 = 18 and x⁶ + 1/x⁶ = 18² − 2 = 322.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x² − 3x + 1 = 0 है, तो x⁶ + 1/x⁶ बराबर है:","optionsHi":["324","322","318","326"],"explanationHi":"x से भाग देने पर: x + 1/x = 3। तब x³ + 1/x³ = 27 − 9 = 18 और x⁶ + 1/x⁶ = 18² − 2 = 322।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-37","question":"In triangle ABC, the bisector of ∠A meets BC at D. If AB = 12 cm, AC = 8 cm and BC = 15 cm, then BD equals:","options":["7.5 cm","6 cm","9 cm","10 cm"],"answer":2,"explanation":"By the angle-bisector theorem BD : DC = AB : AC = 3 : 2, so BD = 3/5 × 15 = 9 cm.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"त्रिभुज ABC में ∠A का समद्विभाजक BC को D पर मिलता है। यदि AB = 12 cm, AC = 8 cm और BC = 15 cm है, तो BD बराबर है:","optionsHi":["7.5 cm","6 cm","9 cm","10 cm"],"explanationHi":"कोण-समद्विभाजक प्रमेय से BD : DC = AB : AC = 3 : 2, अतः BD = 3/5 × 15 = 9 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-38","question":"The value of sin²1° + sin²2° + sin²3° + … + sin²89° is:","options":["89","44","44.5","45"],"answer":2,"explanation":"Pair sin²k° with sin²(90 − k)° = cos²k°, giving 1 per pair: 44 pairs (1° to 44° with 89° to 46°) plus sin²45° = 1/2, total 44.5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"sin²1° + sin²2° + sin²3° + … + sin²89° का मान है:","optionsHi":["89","44","44.5","45"],"explanationHi":"sin²k° को sin²(90 − k)° = cos²k° के साथ जोड़ी बनाने पर प्रत्येक जोड़ी का योग 1 आता है: 44 जोड़ियाँ (1° से 44° तक और 89° से 46° तक) तथा sin²45° = 1/2, कुल 44.5।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-39","question":"If x + 1/x = 1, then x³ + 1/x³ equals:","options":["−2","−1","0","2"],"answer":0,"explanation":"x³ + 1/x³ = 1³ − 3 × 1 = −2. (Indeed x² − x + 1 = 0 gives x³ = −1, so x³ + 1/x³ = −1 − 1 = −2.)","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x + 1/x = 1 है, तो x³ + 1/x³ बराबर है:","optionsHi":["−2","−1","0","2"],"explanationHi":"x³ + 1/x³ = 1³ − 3 × 1 = −2। (वास्तव में x² − x + 1 = 0 से x³ = −1 मिलता है, अतः x³ + 1/x³ = −1 − 1 = −2।)","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-40","question":"A 1.6 m tall observer sees the top of a 21.6 m tall tower at an angle of elevation of 45°. He walks towards the tower until the angle becomes 60°. How far did he walk?","options":["20(√3 − 1) m","20/√3 m","20(1 − 1/√3) m","21.6(1 − 1/√3) m"],"answer":2,"explanation":"Measured from eye level the tower rises 21.6 − 1.6 = 20 m. Distances: 20/tan 45° = 20 and 20/tan 60° = 20/√3, so he walked 20(1 − 1/√3) ≈ 8.45 m. Using 21.6 m forgets the observer’s height.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"1.6 m लंबा एक प्रेक्षक 21.6 m ऊँची मीनार के शीर्ष को 45° के उन्नयन कोण पर देखता है। वह मीनार की ओर तब तक चलता है जब तक कोण 60° नहीं हो जाता। वह कितनी दूर चला?","optionsHi":["20(√3 − 1) m","20/√3 m","20(1 − 1/√3) m","21.6(1 − 1/√3) m"],"explanationHi":"आँख के स्तर से मापने पर मीनार 21.6 − 1.6 = 20 m ऊँची है। दूरियाँ: 20/tan 45° = 20 और 20/tan 60° = 20/√3, अतः वह 20(1 − 1/√3) ≈ 8.45 m चला। 21.6 m का उपयोग करने पर प्रेक्षक की ऊँचाई छूट जाती है।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-41","question":"What is each interior angle of a regular octagon?","options":["45°","135°","120°","140°"],"answer":1,"explanation":"Sum of interior angles = (8 − 2) × 180° = 1,080°, so each = 1,080/8 = 135°. 45° is the exterior angle.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक सम अष्टभुज का प्रत्येक आंतरिक कोण कितना होता है?","optionsHi":["45°","135°","120°","140°"],"explanationHi":"आंतरिक कोणों का योग = (8 − 2) × 180° = 1,080°, अतः प्रत्येक कोण = 1,080/8 = 135°। 45° बाह्य कोण है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-42","question":"What is the value of cos²30° + sin²60°?","options":["3/4","3/2","1","1/2"],"answer":1,"explanation":"cos 30° = sin 60° = √3/2, so the sum is 3/4 + 3/4 = 3/2. It is not 1, because the angles are not the same.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"cos²30° + sin²60° का मान क्या है?","optionsHi":["3/4","3/2","1","1/2"],"explanationHi":"cos 30° = sin 60° = √3/2, अतः योगफल 3/4 + 3/4 = 3/2 है। यह 1 नहीं है, क्योंकि दोनों कोण समान नहीं हैं।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-43","question":"(a + b)² − (a − b)² is equal to:","options":["2ab","0","4ab","2(a² + b²)"],"answer":2,"explanation":"(a² + 2ab + b²) − (a² − 2ab + b²) = 4ab. 2(a² + b²) is the sum, not the difference.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"(a + b)² − (a − b)² बराबर है:","optionsHi":["2ab","0","4ab","2(a² + b²)"],"explanationHi":"(a² + 2ab + b²) − (a² − 2ab + b²) = 4ab। 2(a² + b²) योगफल है, अंतर नहीं।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-44","question":"What is the slope of the line 3x + 4y = 12?","options":["4/3","−3/4","3/4","−4/3"],"answer":1,"explanation":"Rewrite as y = −(3/4)x + 3, so the slope is −a/b = −3/4. 3/4 drops the minus sign, and −4/3 inverts the ratio by using −b/a.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"रेखा 3x + 4y = 12 की ढाल (slope) क्या है?","optionsHi":["4/3","−3/4","3/4","−4/3"],"explanationHi":"इसे y = −(3/4)x + 3 के रूप में लिखने पर ढाल −a/b = −3/4 है। 3/4 में ऋण चिह्न छूट गया है, और −4/3 में −b/a लेकर अनुपात उलट दिया गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-45","question":"One angle of a triangle is 50° and the other two angles are equal. What is each of them?","options":["130°","65°","75°","50°"],"answer":1,"explanation":"The two equal angles share 180° − 50° = 130°, so each is 130° ÷ 2 = 65°. Picking 130° forgets to split the remainder between the two angles.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक त्रिभुज का एक कोण 50° है और अन्य दो कोण बराबर हैं। उनमें से प्रत्येक कितना है?","optionsHi":["130°","65°","75°","50°"],"explanationHi":"दोनों बराबर कोणों का योग 180° − 50° = 130° है, अतः प्रत्येक 130° ÷ 2 = 65° है। 130° चुनने पर शेष को दोनों कोणों में बाँटना भूल गए।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-46","question":"If x − 1/x = 4, then x³ − 1/x³ equals:","options":["64","52","76","68"],"answer":2,"explanation":"x³ − 1/x³ = (x − 1/x)³ + 3(x − 1/x) = 64 + 12 = 76. Subtracting 3 × 4 (as for a sum) gives 52.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि x − 1/x = 4 है, तो x³ − 1/x³ बराबर है:","optionsHi":["64","52","76","68"],"explanationHi":"x³ − 1/x³ = (x − 1/x)³ + 3(x − 1/x) = 64 + 12 = 76। 3 × 4 को घटाने (जैसा योग के लिए होता है) पर 52 आता है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-47","question":"If a + b + c = 0 (a, b, c non-zero), then a²/bc + b²/ca + c²/ab equals:","options":["abc","0","1","3"],"answer":3,"explanation":"The expression = (a³ + b³ + c³)/abc, and when a + b + c = 0, a³ + b³ + c³ = 3abc, so it equals 3.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि a + b + c = 0 है (a, b, c शून्येतर), तो a²/bc + b²/ca + c²/ab बराबर है:","optionsHi":["abc","0","1","3"],"explanationHi":"व्यंजक = (a³ + b³ + c³)/abc, और जब a + b + c = 0 हो तो a³ + b³ + c³ = 3abc, अतः यह 3 के बराबर है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-48","question":"√(7 + 4√3) is equal to:","options":["2 + √3","4 + √3","2√3 + 1","√3 + 1"],"answer":0,"explanation":"7 + 4√3 = 4 + 3 + 2 × 2 × √3 = (2 + √3)², so the square root is 2 + √3.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"√(7 + 4√3) बराबर है:","optionsHi":["2 + √3","4 + √3","2√3 + 1","√3 + 1"],"explanationHi":"7 + 4√3 = 4 + 3 + 2 × 2 × √3 = (2 + √3)², अतः वर्गमूल 2 + √3 है।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-49","question":"What is the area of the triangle formed by the line 3x + 4y = 12 and the coordinate axes?","options":["6 sq units","12 sq units","7 sq units","24 sq units"],"answer":0,"explanation":"The intercepts are x = 4 and y = 3, so the area = ½ × 4 × 3 = 6 sq units. 12 forgets the ½.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"रेखा 3x + 4y = 12 और निर्देशांक अक्षों से बने त्रिभुज का क्षेत्रफल कितना है?","optionsHi":["6 वर्ग इकाई","12 वर्ग इकाई","7 वर्ग इकाई","24 वर्ग इकाई"],"explanationHi":"अंतःखंड x = 4 और y = 3 हैं, अतः क्षेत्रफल = ½ × 4 × 3 = 6 वर्ग इकाई। 12 में ½ छूट गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-50","question":"How many diagonals does a polygon with 12 sides have?","options":["54","60","66","48"],"answer":0,"explanation":"Diagonals = n(n − 3)/2 = 12 × 9/2 = 54. 66 = ¹²C₂ also counts the 12 sides.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"12 भुजाओं वाले बहुभुज के कितने विकर्ण होते हैं?","optionsHi":["54","60","66","48"],"explanationHi":"विकर्णों की संख्या = n(n − 3)/2 = 12 × 9/2 = 54। 66 = ¹²C₂ में 12 भुजाएँ भी गिन ली गई हैं।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-51","question":"Each exterior angle of a regular polygon is 24°. How many sides does it have?","options":["18","12","15","24"],"answer":2,"explanation":"The exterior angles add up to 360°, so the number of sides = 360/24 = 15.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक सम बहुभुज का प्रत्येक बाह्य कोण 24° है। उसकी कितनी भुजाएँ हैं?","optionsHi":["18","12","15","24"],"explanationHi":"बाह्य कोणों का योग 360° होता है, अतः भुजाओं की संख्या = 360/24 = 15।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-52","question":"What is the value of tan 1° × tan 2° × tan 3° × … × tan 89°?","options":["1","0","Not defined","√3"],"answer":0,"explanation":"Pair tan θ with tan(90° − θ) = cot θ: each pair gives 1, and the middle term tan 45° = 1, so the product is 1.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"tan 1° × tan 2° × tan 3° × … × tan 89° का मान क्या है?","optionsHi":["1","0","परिभाषित नहीं","√3"],"explanationHi":"tan θ को tan(90° − θ) = cot θ के साथ जोड़ी बनाएँ: प्रत्येक जोड़ी का गुणनफल 1 है, और मध्य पद tan 45° = 1 है, अतः गुणनफल 1 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-53","question":"A 13 m long ladder rests against a wall and reaches a window 12 m above the ground. How far is the foot of the ladder from the wall?","options":["1 m","6 m","5 m","√313 m"],"answer":2,"explanation":"The ladder is the hypotenuse: distance = √(13² − 12²) = √25 = 5 m (a 5-12-13 triple). √313 m adds the squares, treating the ladder as a leg instead of the hypotenuse.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"13 m लंबी एक सीढ़ी दीवार से टिकी है और जमीन से 12 m ऊपर एक खिड़की तक पहुँचती है। सीढ़ी का निचला सिरा दीवार से कितनी दूर है?","optionsHi":["1 m","6 m","5 m","√313 m"],"explanationHi":"सीढ़ी कर्ण है: दूरी = √(13² − 12²) = √25 = 5 m (5-12-13 त्रिक)। √313 m में वर्गों को जोड़ दिया गया है, यानी सीढ़ी को कर्ण के बजाय एक भुजा मान लिया गया है।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-54","question":"What is the distance between the points (3, −4) and (−5, 2)?","options":["10 units","14 units","8 units","√68 units"],"answer":0,"explanation":"Distance = √[(3 + 5)² + (−4 − 2)²] = √(64 + 36) = 10. √68 comes from subtracting −5 and −4 with the wrong signs.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"बिंदुओं (3, −4) और (−5, 2) के बीच की दूरी क्या है?","optionsHi":["10 इकाई","14 इकाई","8 इकाई","√68 इकाई"],"explanationHi":"दूरी = √[(3 + 5)² + (−4 − 2)²] = √(64 + 36) = 10। √68 तब आता है जब −5 और −4 को गलत चिह्नों के साथ घटाया जाए।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-55","question":"If x² − 5x + 1 = 0, then x³ + 1/x³ equals:","options":["140","125","115","110"],"answer":3,"explanation":"Dividing by x gives x + 1/x = 5, so x³ + 1/x³ = 5³ − 3 × 5 = 125 − 15 = 110.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"यदि x² − 5x + 1 = 0 है, तो x³ + 1/x³ बराबर है:","optionsHi":["140","125","115","110"],"explanationHi":"x से भाग देने पर x + 1/x = 5, अतः x³ + 1/x³ = 5³ − 3 × 5 = 125 − 15 = 110।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-56","question":"If α and β are the roots of x² − 7x + 10 = 0, then α² + β² equals:","options":["49","29","20","69"],"answer":1,"explanation":"α + β = 7 and αβ = 10, so α² + β² = 49 − 20 = 29 (the roots are 2 and 5: 4 + 25 = 29).","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"यदि α और β समीकरण x² − 7x + 10 = 0 के मूल हैं, तो α² + β² बराबर है:","optionsHi":["49","29","20","69"],"explanationHi":"α + β = 7 और αβ = 10, अतः α² + β² = 49 − 20 = 29 (मूल 2 और 5 हैं: 4 + 25 = 29)।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-57","question":"What is the remainder when x³ − 2x² + 4x − 5 is divided by (x − 2)?","options":["11","3","−3","−5"],"answer":1,"explanation":"By the remainder theorem, put x = 2: 8 − 8 + 8 − 5 = 3. −5 is just the constant term (as if x = 0), and −3 comes from a sign slip in the last step; no long division is needed.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"x³ − 2x² + 4x − 5 को (x − 2) से भाग देने पर शेषफल क्या होगा?","optionsHi":["11","3","−3","−5"],"explanationHi":"शेषफल प्रमेय से x = 2 रखें: 8 − 8 + 8 − 5 = 3। −5 केवल अचर पद है (मानो x = 0 हो), और −3 अंतिम चरण में चिह्न की गलती से आता है; लंबी विभाजन विधि की आवश्यकता नहीं है।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-58","question":"What is the maximum value of 5 sin θ + 12 cos θ?","options":["7","12","13","17"],"answer":2,"explanation":"The maximum of a sin θ + b cos θ is √(a² + b²) = √(25 + 144) = 13. Adding 5 + 12 = 17 ignores that sin θ and cos θ cannot both be 1.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"5 sin θ + 12 cos θ का अधिकतम मान क्या है?","optionsHi":["7","12","13","17"],"explanationHi":"a sin θ + b cos θ का अधिकतम मान √(a² + b²) = √(25 + 144) = 13 होता है। 5 + 12 = 17 जोड़ने पर यह अनदेखा हो जाता है कि sin θ और cos θ दोनों एक साथ 1 नहीं हो सकते।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-59","question":"sin⁶θ + cos⁶θ + 3 sin²θ cos²θ equals:","options":["1","3","0","2"],"answer":0,"explanation":"a³ + b³ = (a + b)³ − 3ab(a + b) with a = sin²θ, b = cos²θ, a + b = 1 gives sin⁶θ + cos⁶θ = 1 − 3 sin²θ cos²θ, so the expression is 1.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"sin⁶θ + cos⁶θ + 3 sin²θ cos²θ बराबर है:","optionsHi":["1","3","0","2"],"explanationHi":"a³ + b³ = (a + b)³ − 3ab(a + b) में a = sin²θ, b = cos²θ, a + b = 1 रखने पर sin⁶θ + cos⁶θ = 1 − 3 sin²θ cos²θ, अतः व्यंजक का मान 1 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-60","question":"Two circles of radii 8 cm and 3 cm have their centres 13 cm apart. What is the length of a direct common tangent?","options":["10 cm","11 cm","√120 cm","12 cm"],"answer":3,"explanation":"Direct common tangent = √[d² − (r₁ − r₂)²] = √(169 − 25) = 12 cm. Using (r₁ + r₂)² gives √48, the transverse tangent.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"8 cm और 3 cm त्रिज्या वाले दो वृत्तों के केंद्र 13 cm की दूरी पर हैं। एक उभयनिष्ठ बाह्य स्पर्श रेखा की लंबाई कितनी है?","optionsHi":["10 cm","11 cm","√120 cm","12 cm"],"explanationHi":"उभयनिष्ठ बाह्य स्पर्श रेखा = √[d² − (r₁ − r₂)²] = √(169 − 25) = 12 cm। (r₁ + r₂)² लेने पर √48 आता है, जो अनुप्रस्थ उभयनिष्ठ स्पर्श रेखा है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-61","question":"In a triangle with sides 6 cm, 8 cm and 10 cm, what is the length of the median drawn to the longest side?","options":["5 cm","6 cm","√73 cm","4.8 cm"],"answer":0,"explanation":"By Apollonius, m = ½√(2 × 36 + 2 × 64 − 100) = ½√100 = 5 cm (the median to the hypotenuse equals half of it). 4.8 cm is the altitude.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"6 cm, 8 cm और 10 cm भुजाओं वाले त्रिभुज में सबसे लंबी भुजा पर खींची गई माध्यिका की लंबाई कितनी है?","optionsHi":["5 cm","6 cm","√73 cm","4.8 cm"],"explanationHi":"अपोलोनियस प्रमेय से m = ½√(2 × 36 + 2 × 64 − 100) = ½√100 = 5 cm (कर्ण पर माध्यिका उसकी आधी होती है)। 4.8 cm शीर्षलंब है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-62","question":"What are the coordinates of the point that divides the line segment joining (2, 3) and (8, 9) internally in the ratio 1 : 2?","options":["(4, 5)","(6, 7)","(5, 6)","(4, 6)"],"answer":0,"explanation":"Point = ((1 × 8 + 2 × 2)/3, (1 × 9 + 2 × 3)/3) = (12/3, 15/3) = (4, 5). (6, 7) divides it in the ratio 2 : 1.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"बिंदुओं (2, 3) और (8, 9) को मिलाने वाले रेखाखंड को 1 : 2 के अनुपात में अंतः विभाजित करने वाले बिंदु के निर्देशांक क्या हैं?","optionsHi":["(4, 5)","(6, 7)","(5, 6)","(4, 6)"],"explanationHi":"बिंदु = ((1 × 8 + 2 × 2)/3, (1 × 9 + 2 × 3)/3) = (12/3, 15/3) = (4, 5)। (6, 7) इसे 2 : 1 के अनुपात में बाँटता है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-63","question":"From an external point P, a tangent PT and a secant PAB are drawn to a circle, with PA = 4 cm and AB = 5 cm. What is PT?","options":["9 cm","√20 cm","6 cm","4.5 cm"],"answer":2,"explanation":"PT² = PA × PB = 4 × (4 + 5) = 36, so PT = 6 cm. Using PA × AB = 20 is the common slip.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"बाह्य बिंदु P से एक वृत्त पर स्पर्श रेखा PT और छेदक रेखा PAB खींची गई हैं, जहाँ PA = 4 cm और AB = 5 cm है। PT कितना है?","optionsHi":["9 cm","√20 cm","6 cm","4.5 cm"],"explanationHi":"PT² = PA × PB = 4 × (4 + 5) = 36, अतः PT = 6 cm। PA × AB = 20 लेना आम गलती है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-64","question":"The angles of a triangle are in the ratio 2 : 3 : 4. What is the difference between the largest and the smallest angle?","options":["80°","40°","60°","20°"],"answer":1,"explanation":"The angles are 40°, 60° and 80° (180/9 = 20 per part), so the difference is 80° − 40° = 40°.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"एक त्रिभुज के कोण 2 : 3 : 4 के अनुपात में हैं। सबसे बड़े और सबसे छोटे कोण का अंतर कितना है?","optionsHi":["80°","40°","60°","20°"],"explanationHi":"कोण 40°, 60° और 80° हैं (180/9 = 20 प्रति भाग), अतः अंतर 80° − 40° = 40° है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-65","question":"If 9ˣ = 27ˣ⁻¹, then x equals:","options":["2","3","1","−3"],"answer":1,"explanation":"Write both sides as powers of 3: 3²ˣ = 3³⁽ˣ⁻¹⁾, so 2x = 3x − 3 and x = 3. Getting x = 1 comes from forgetting to multiply the −1 by 3 (2x = 3x − 1).","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"यदि 9ˣ = 27ˣ⁻¹ है, तो x बराबर है:","optionsHi":["2","3","1","−3"],"explanationHi":"दोनों पक्षों को 3 की घात के रूप में लिखें: 3²ˣ = 3³⁽ˣ⁻¹⁾, अतः 2x = 3x − 3 और x = 3। x = 1 तब आता है जब −1 को 3 से गुणा करना भूल जाएँ (2x = 3x − 1)।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-66","question":"The shadow of a tower is √3 times its height. What is the angle of elevation of the sun?","options":["30°","60°","15°","45°"],"answer":0,"explanation":"tan θ = height/shadow = 1/√3, so θ = 30°. 60° comes from inverting the ratio.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"किसी मीनार की छाया उसकी ऊँचाई की √3 गुना है। सूर्य का उन्नयन कोण कितना है?","optionsHi":["30°","60°","15°","45°"],"explanationHi":"tan θ = ऊँचाई/छाया = 1/√3, अतः θ = 30°। 60° अनुपात को उलटने से आता है।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-67","question":"In triangle ABC, AB = 13 cm, AC = 15 cm and BC = 14 cm. AD is perpendicular to BC. What is AD?","options":["12 cm","11 cm","14 cm","13.5 cm"],"answer":0,"explanation":"By Heron's formula, s = 21 and area = √(21 × 8 × 6 × 7) = 84 cm². AD = 2 × 84/14 = 12 cm.","difficulty":"hard","source":"SSC CGL Tier 2 · SSC CHSL","questionHi":"त्रिभुज ABC में AB = 13 cm, AC = 15 cm और BC = 14 cm है। AD, BC पर लंब है। AD कितना है?","optionsHi":["12 cm","11 cm","14 cm","13.5 cm"],"explanationHi":"हीरोन के सूत्र से s = 21 और क्षेत्रफल = √(21 × 8 × 6 × 7) = 84 cm²। AD = 2 × 84/14 = 12 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-68","question":"How many of the following statements are correct?\nI. The angle in a semicircle is a right angle.\nII. The opposite angles of a cyclic quadrilateral are equal.\nIII. The tangent at any point of a circle is perpendicular to the radius through that point.\nIV. Equal chords of a circle subtend equal angles at the centre.","options":["All four","Only two","Only one","Only three"],"answer":3,"explanation":"I, III and IV are true. II is false: the opposite angles of a cyclic quadrilateral are supplementary (they add up to 180°), not equal.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\nI. अर्धवृत्त में बना कोण समकोण होता है।\nII. चक्रीय चतुर्भुज के सम्मुख कोण बराबर होते हैं।\nIII. वृत्त के किसी बिंदु पर स्पर्श रेखा उस बिंदु से जाने वाली त्रिज्या पर लंब होती है।\nIV. वृत्त की बराबर जीवाएँ केंद्र पर बराबर कोण बनाती हैं।","optionsHi":["चारों","केवल दो","केवल एक","केवल तीन"],"explanationHi":"I, III और IV सत्य हैं। II असत्य है: चक्रीय चतुर्भुज के सम्मुख कोण संपूरक होते हैं (उनका योग 180° होता है), बराबर नहीं।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-69","question":"If a + b + c = 6, a² + b² + c² = 14 and a³ + b³ + c³ = 36, then abc equals:","options":["12","6","11","4"],"answer":1,"explanation":"ab + bc + ca = (36 − 14)/2 = 11. a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) gives 36 − 3abc = 6 × 3 = 18, so abc = 6 (a, b, c = 1, 2, 3). 11 is ab + bc + ca.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि a + b + c = 6, a² + b² + c² = 14 और a³ + b³ + c³ = 36 है, तो abc बराबर है:","optionsHi":["12","6","11","4"],"explanationHi":"ab + bc + ca = (36 − 14)/2 = 11। a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) से 36 − 3abc = 6 × 3 = 18, अतः abc = 6 (a, b, c = 1, 2, 3)। 11 तो ab + bc + ca है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-70","question":"If a = 2025, b = 2024 and c = 2023, then a³ + b³ + c³ − 3abc equals:","options":["12,144","18,216","0","6,072"],"answer":1,"explanation":"a³ + b³ + c³ − 3abc = ½(a + b + c)[(a − b)² + (b − c)² + (c − a)²] = ½ × 6,072 × (1 + 1 + 4) = 18,216.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि a = 2025, b = 2024 और c = 2023 है, तो a³ + b³ + c³ − 3abc बराबर है:","optionsHi":["12,144","18,216","0","6,072"],"explanationHi":"a³ + b³ + c³ − 3abc = ½(a + b + c)[(a − b)² + (b − c)² + (c − a)²] = ½ × 6,072 × (1 + 1 + 4) = 18,216।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-71","question":"If x = 1/(√2 + 1), then x² + 2x equals:","options":["√2","2","3 − 2√2","1"],"answer":3,"explanation":"Rationalising, x = √2 − 1, so x + 1 = √2 and x² + 2x = (x + 1)² − 1 = 2 − 1 = 1. 3 − 2√2 is x² alone.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि x = 1/(√2 + 1) है, तो x² + 2x बराबर है:","optionsHi":["√2","2","3 − 2√2","1"],"explanationHi":"परिमेयीकरण करने पर x = √2 − 1, अतः x + 1 = √2 और x² + 2x = (x + 1)² − 1 = 2 − 1 = 1। 3 − 2√2 केवल x² है।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-72","question":"What is the value of (√5 + √3)/(√5 − √3) + (√5 − √3)/(√5 + √3)?","options":["4","2√15","8","16"],"answer":2,"explanation":"Over the common denominator 5 − 3 = 2: [(√5 + √3)² + (√5 − √3)²]/2 = [2(5 + 3)]/2 = 8.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"(√5 + √3)/(√5 − √3) + (√5 − √3)/(√5 + √3) का मान क्या है?","optionsHi":["4","2√15","8","16"],"explanationHi":"उभयनिष्ठ हर 5 − 3 = 2 लेने पर: [(√5 + √3)² + (√5 − √3)²]/2 = [2(5 + 3)]/2 = 8।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-73","question":"If cosec θ − cot θ = 1/2, then cos θ equals:","options":["3/4","4/5","5/4","3/5"],"answer":3,"explanation":"Since cosec²θ − cot²θ = 1, cosec θ + cot θ = 2. Adding and subtracting: cosec θ = 5/4 and cot θ = 3/4, so cos θ = cot θ/cosec θ = 3/5. 4/5 is sin θ.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि cosec θ − cot θ = 1/2 है, तो cos θ बराबर है:","optionsHi":["3/4","4/5","5/4","3/5"],"explanationHi":"चूँकि cosec²θ − cot²θ = 1, इसलिए cosec θ + cot θ = 2। जोड़ने और घटाने पर: cosec θ = 5/4 और cot θ = 3/4, अतः cos θ = cot θ/cosec θ = 3/5। 4/5 तो sin θ है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-74","question":"Two towers of equal height stand 80 m apart. From a point on the ground between them, the angles of elevation of their tops are 60° and 30°. What is the height of each tower?","options":["40√3 m","20 m","20√3 m","40 m"],"answer":2,"explanation":"If the height is h, the distances to the feet are h/√3 and h√3, so h/√3 + h√3 = 4h/√3 = 80 and h = 20√3 m (≈ 34.6 m).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"समान ऊँचाई की दो मीनारें एक-दूसरे से 80 m की दूरी पर खड़ी हैं। उनके बीच जमीन पर स्थित एक बिंदु से उनके शीर्षों के उन्नयन कोण 60° और 30° हैं। प्रत्येक मीनार की ऊँचाई कितनी है?","optionsHi":["40√3 m","20 m","20√3 m","40 m"],"explanationHi":"यदि ऊँचाई h है, तो आधारों तक की दूरियाँ h/√3 और h√3 हैं, अतः h/√3 + h√3 = 4h/√3 = 80 और h = 20√3 m (≈ 34.6 m)।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-75","question":"From the top of a 100 m high cliff, the angles of depression of two boats on the same side, in line with the foot of the cliff, are 60° and 45°. What is the distance between the boats?","options":["50(3 − √3) m","100√3 m","100(√3 − 1) m","100(3 − √3)/3 m"],"answer":3,"explanation":"The boats are 100/tan 45° = 100 m and 100/tan 60° = 100/√3 m from the foot. Distance = 100 − 100/√3 = 100(3 − √3)/3 m ≈ 42.3 m.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"100 m ऊँची चट्टान के शीर्ष से, चट्टान के आधार के साथ एक ही सीधी रेखा में और एक ही ओर स्थित दो नावों के अवनमन कोण 60° और 45° हैं। दोनों नावों के बीच की दूरी कितनी है?","optionsHi":["50(3 − √3) m","100√3 m","100(√3 − 1) m","100(3 − √3)/3 m"],"explanationHi":"नावें आधार से 100/tan 45° = 100 m और 100/tan 60° = 100/√3 m दूर हैं। दूरी = 100 − 100/√3 = 100(3 − √3)/3 m ≈ 42.3 m।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-76","question":"For how many real values of k is the area of the triangle with vertices (0, 0), (4, 0) and (k, 6) equal to 12 square units?","options":["Only k = 2","No value of k","Only k = 0","Every real value of k"],"answer":3,"explanation":"The base on the x-axis is 4 and the height is always 6 (the y-coordinate of the third vertex), so the area is ½ × 4 × 6 = 12 whatever k is.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"k के कितने वास्तविक मानों के लिए शीर्षों (0, 0), (4, 0) और (k, 6) वाले त्रिभुज का क्षेत्रफल 12 वर्ग इकाई होगा?","optionsHi":["केवल k = 2","k का कोई मान नहीं","केवल k = 0","k का प्रत्येक वास्तविक मान"],"explanationHi":"x-अक्ष पर आधार 4 है और ऊँचाई सदैव 6 है (तीसरे शीर्ष का y-निर्देशांक), अतः k कुछ भी हो, क्षेत्रफल ½ × 4 × 6 = 12 रहता है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-77","question":"For a triangle with sides 7 cm, 24 cm and 25 cm, what is the sum of its circumradius and its inradius?","options":["16 cm","15 cm","15.5 cm","12.5 cm"],"answer":2,"explanation":"It is right-angled (49 + 576 = 625), so R = 25/2 = 12.5 cm and r = (7 + 24 − 25)/2 = 3 cm. Sum = 15.5 cm.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"7 cm, 24 cm और 25 cm भुजाओं वाले त्रिभुज की परित्रिज्या और अंतःत्रिज्या का योग कितना है?","optionsHi":["16 cm","15 cm","15.5 cm","12.5 cm"],"explanationHi":"यह समकोण त्रिभुज है (49 + 576 = 625), अतः R = 25/2 = 12.5 cm और r = (7 + 24 − 25)/2 = 3 cm। योग = 15.5 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-78","question":"The three medians of a triangle are 9 cm, 12 cm and 15 cm long. What is the area of the triangle?","options":["36 cm²","54 cm²","72 cm²","108 cm²"],"answer":2,"explanation":"Area of a triangle = 4/3 × area of the triangle formed by its medians. The medians 9, 12, 15 form a right triangle of area 54, so the area = 4/3 × 54 = 72 cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक त्रिभुज की तीनों माध्यिकाएँ 9 cm, 12 cm और 15 cm लंबी हैं। त्रिभुज का क्षेत्रफल कितना है?","optionsHi":["36 cm²","54 cm²","72 cm²","108 cm²"],"explanationHi":"त्रिभुज का क्षेत्रफल = उसकी माध्यिकाओं से बने त्रिभुज के क्षेत्रफल का 4/3 गुना। माध्यिकाएँ 9, 12, 15 एक समकोण त्रिभुज बनाती हैं जिसका क्षेत्रफल 54 है, अतः क्षेत्रफल = 4/3 × 54 = 72 cm²।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-79","question":"How many triangles with integer sides have a perimeter of 12 units?","options":["4","2","5","3"],"answer":3,"explanation":"Each side must be less than half the perimeter (< 6): (2, 5, 5), (3, 4, 5) and (4, 4, 4). So 3 triangles.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"पूर्णांक भुजाओं वाले कितने त्रिभुजों का परिमाप 12 इकाई है?","optionsHi":["4","2","5","3"],"explanationHi":"प्रत्येक भुजा परिमाप के आधे से छोटी (< 6) होनी चाहिए: (2, 5, 5), (3, 4, 5) और (4, 4, 4)। अतः 3 त्रिभुज।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-80","question":"A chord of a circle of radius 6 cm subtends an angle of 120° at the centre. What is the area of the minor segment it cuts off?","options":["(12π − 9√3) cm²","12π cm²","(6π − 9√3) cm²","(12π − 18√3) cm²"],"answer":0,"explanation":"Sector = 120/360 × π × 36 = 12π. Triangle = ½ × 6 × 6 × sin 120° = 9√3. Segment = 12π − 9√3 cm² (≈ 22.1 cm²).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"6 cm त्रिज्या वाले वृत्त की एक जीवा केंद्र पर 120° का कोण बनाती है। उसके द्वारा कटे लघु वृत्तखंड का क्षेत्रफल कितना है?","optionsHi":["(12π − 9√3) cm²","12π cm²","(6π − 9√3) cm²","(12π − 18√3) cm²"],"explanationHi":"त्रिज्यखंड = 120/360 × π × 36 = 12π। त्रिभुज = ½ × 6 × 6 × sin 120° = 9√3। वृत्तखंड = 12π − 9√3 cm² (≈ 22.1 cm²)।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-81","question":"TA is a tangent to a circle at A, and AB is a chord with ∠TAB = 65°. D is a point on the arc AB that lies inside ∠TAB (the minor arc). What is ∠ADB?","options":["25°","115°","130°","65°"],"answer":1,"explanation":"The arc inside ∠TAB measures 2 × 65° = 130°, and by the alternate segment theorem every angle in the major segment is 65°. D lies in the minor segment, whose angles are supplementary to those in the major segment, so ∠ADB = 180° − 65° = 115°.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"TA, बिंदु A पर वृत्त की स्पर्श रेखा है और AB एक जीवा है जिसमें ∠TAB = 65° है। D, चाप AB पर ∠TAB के भीतर स्थित (लघु चाप पर) एक बिंदु है। ∠ADB कितना है?","optionsHi":["25°","115°","130°","65°"],"explanationHi":"∠TAB के भीतर का चाप 2 × 65° = 130° का है, और एकांतर वृत्तखंड प्रमेय से दीर्घ वृत्तखंड में बना हर कोण 65° है। D लघु वृत्तखंड में है, जिसके कोण दीर्घ वृत्तखंड के कोणों के संपूरक होते हैं, अतः ∠ADB = 180° − 65° = 115°।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-82","question":"Assertion (A): The maximum value of sin θ cos θ is 1/2.\nReason (R): sin θ cos θ = ½ sin 2θ, and the maximum value of sin 2θ is 1.","options":["Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"½ sin 2θ is largest when sin 2θ = 1 (θ = 45°), giving 1/2. A follows from R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"कथन (A): sin θ cos θ का अधिकतम मान 1/2 है।\nकारण (R): sin θ cos θ = ½ sin 2θ, और sin 2θ का अधिकतम मान 1 है।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है"],"explanationHi":"½ sin 2θ सबसे बड़ा तब होता है जब sin 2θ = 1 (θ = 45°), जिससे मान 1/2 आता है। A, R से ही निकलता है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-83","question":"How many integers x satisfy 2x − 5 < 3x + 1 < 2x + 4?","options":["9","10","6","8"],"answer":3,"explanation":"2x − 5 < 3x + 1 gives x > −6, and 3x + 1 < 2x + 4 gives x < 3, so x = −5, −4, …, 2: that is 8 integers. 9 is the gap 3 − (−6) without adjusting for strict ends, 10 includes both endpoints, and 6 comes from the slip −5 + 1 = −4 giving x > −4.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"कितने पूर्णांक x असमिका 2x − 5 < 3x + 1 < 2x + 4 को संतुष्ट करते हैं?","optionsHi":["9","10","6","8"],"explanationHi":"2x − 5 < 3x + 1 से x > −6 और 3x + 1 < 2x + 4 से x < 3 मिलता है, अतः x = −5, −4, …, 2: यानी 8 पूर्णांक। 9 अंतर 3 − (−6) है जिसमें कठोर सीमाओं का समायोजन नहीं किया गया, 10 में दोनों सिरे गिन लिए गए हैं, और 6 उस भूल से आता है जिसमें −5 + 1 = −4 लेकर x > −4 मान लिया जाता है।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-84","question":"For what value of k do the equations kx + 3y = 5 and 4x + 6y = 7 have no solution?","options":["4","3/2","−2","2"],"answer":3,"explanation":"No solution needs parallel lines: k/4 = 3/6 ≠ 5/7, so k = 2. (5/7 ≠ 1/2, so the lines are distinct.)","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"k के किस मान के लिए समीकरणों kx + 3y = 5 और 4x + 6y = 7 का कोई हल नहीं है?","optionsHi":["4","3/2","−2","2"],"explanationHi":"कोई हल न होने के लिए रेखाएँ समांतर होनी चाहिए: k/4 = 3/6 ≠ 5/7, अतः k = 2। (5/7 ≠ 1/2, इसलिए रेखाएँ भिन्न हैं।)","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-85","question":"(sin θ + cosec θ)² + (cos θ + sec θ)² − (tan²θ + cot²θ) equals:","options":["7","9","1","5"],"answer":0,"explanation":"Expanding: sin²θ + cos²θ + 4 + cosec²θ + sec²θ = 1 + 4 + (1 + cot²θ) + (1 + tan²θ) = 7 + tan²θ + cot²θ. Subtracting tan²θ + cot²θ leaves 7.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"(sin θ + cosec θ)² + (cos θ + sec θ)² − (tan²θ + cot²θ) बराबर है:","optionsHi":["7","9","1","5"],"explanationHi":"प्रसार करने पर: sin²θ + cos²θ + 4 + cosec²θ + sec²θ = 1 + 4 + (1 + cot²θ) + (1 + tan²θ) = 7 + tan²θ + cot²θ। tan²θ + cot²θ घटाने पर 7 शेष रहता है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-86","question":"What is the value of sin²45° + tan²60° − cos 0°?","options":["3/2","7/2","5/2","2"],"answer":2,"explanation":"sin²45° = 1/2, tan²60° = 3 and cos 0° = 1, so the value is 1/2 + 3 − 1 = 5/2.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"sin²45° + tan²60° − cos 0° का मान क्या है?","optionsHi":["3/2","7/2","5/2","2"],"explanationHi":"sin²45° = 1/2, tan²60° = 3 और cos 0° = 1, अतः मान 1/2 + 3 − 1 = 5/2 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-87","question":"Each interior angle of a regular polygon is 150°. How many sides does it have?","options":["10","15","8","12"],"answer":3,"explanation":"Exterior angle = 180° − 150° = 30°, and the exterior angles add up to 360°, so n = 360/30 = 12.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक सम बहुभुज का प्रत्येक आंतरिक कोण 150° है। उसकी कितनी भुजाएँ हैं?","optionsHi":["10","15","8","12"],"explanationHi":"बाह्य कोण = 180° − 150° = 30°, और बाह्य कोणों का योग 360° होता है, अतः n = 360/30 = 12।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-88","question":"What is the midpoint of the line segment joining (−2, 7) and (6, −1)?","options":["(2, 3)","(4, 4)","(2, 4)","(−4, 4)"],"answer":0,"explanation":"Midpoint = ((−2 + 6)/2, (7 + (−1))/2) = (2, 3). (4, 4) halves the differences instead of the sums.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"बिंदुओं (−2, 7) और (6, −1) को मिलाने वाले रेखाखंड का मध्य बिंदु क्या है?","optionsHi":["(2, 3)","(4, 4)","(2, 4)","(−4, 4)"],"explanationHi":"मध्य बिंदु = ((−2 + 6)/2, (7 + (−1))/2) = (2, 3)। (4, 4) में योग के बजाय अंतरों को आधा किया गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-89","question":"If x + y = 7 and x − y = 3, what is the value of x² − y² + 2xy?","options":["21","41","49","45"],"answer":1,"explanation":"x² − y² = (x + y)(x − y) = 21, and x = 5, y = 2 give 2xy = 20. Total = 41. 49 is (x + y)², a different expression.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि x + y = 7 और x − y = 3 है, तो x² − y² + 2xy का मान क्या है?","optionsHi":["21","41","49","45"],"explanationHi":"x² − y² = (x + y)(x − y) = 21, और x = 5, y = 2 से 2xy = 20। कुल = 41। 49 तो (x + y)² है, जो एक अलग व्यंजक है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-90","question":"If a + 1/a = 6 and a > 1, what is the value of a² − 1/a²?","options":["32","34","24√2","12√2"],"answer":2,"explanation":"(a − 1/a)² = (a + 1/a)² − 4 = 32, so a − 1/a = 4√2 (positive as a > 1). a² − 1/a² = (a + 1/a)(a − 1/a) = 6 × 4√2 = 24√2.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि a + 1/a = 6 और a > 1 है, तो a² − 1/a² का मान क्या है?","optionsHi":["32","34","24√2","12√2"],"explanationHi":"(a − 1/a)² = (a + 1/a)² − 4 = 32, अतः a − 1/a = 4√2 (धनात्मक, क्योंकि a > 1)। a² − 1/a² = (a + 1/a)(a − 1/a) = 6 × 4√2 = 24√2।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-91","question":"In triangle ABC, ∠B = 90°, AB = 9 cm and AC = 15 cm. What is the value of tan C + sec A?","options":["31/12","7/4","17/12","29/12"],"answer":3,"explanation":"BC = √(225 − 81) = 12. tan C = AB/BC = 3/4 and sec A = AC/AB = 5/3, so the sum is 9/12 + 20/12 = 29/12.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"त्रिभुज ABC में ∠B = 90°, AB = 9 cm और AC = 15 cm है। tan C + sec A का मान क्या है?","optionsHi":["31/12","7/4","17/12","29/12"],"explanationHi":"BC = √(225 − 81) = 12। tan C = AB/BC = 3/4 और sec A = AC/AB = 5/3, अतः योगफल 9/12 + 20/12 = 29/12 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-92","question":"Two supplementary angles differ by 36°. What is the larger angle?","options":["108°","72°","126°","96°"],"answer":0,"explanation":"Larger = (sum + difference)/2 = (180 + 36)/2 = 108°. 72° is the smaller angle.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"दो संपूरक कोणों का अंतर 36° है। बड़ा कोण कितना है?","optionsHi":["108°","72°","126°","96°"],"explanationHi":"बड़ा कोण = (योग + अंतर)/2 = (180 + 36)/2 = 108°। 72° छोटा कोण है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-93","question":"An exterior angle of a triangle is 120°, and its two interior opposite angles are in the ratio 3 : 5. What is the smallest angle of the triangle?","options":["60°","45°","75°","40°"],"answer":1,"explanation":"The interior opposite angles add up to the exterior angle: 3k + 5k = 120°, so they are 45° and 75°. The third angle is 180° − 120° = 60°, so the smallest is 45°.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक त्रिभुज का बाह्य कोण 120° है, और उसके दोनों अंतःसम्मुख कोण 3 : 5 के अनुपात में हैं। त्रिभुज का सबसे छोटा कोण कितना है?","optionsHi":["60°","45°","75°","40°"],"explanationHi":"अंतःसम्मुख कोणों का योग बाह्य कोण के बराबर होता है: 3k + 5k = 120°, अतः वे 45° और 75° हैं। तीसरा कोण 180° − 120° = 60° है, इसलिए सबसे छोटा 45° है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-94","question":"A line passes through (2, 3) and is parallel to 2x − 5y + 7 = 0. What is its y-intercept?","options":["−11/5","3/5","11/5","11/2"],"answer":2,"explanation":"A parallel line has slope 2/5: y − 3 = (2/5)(x − 2). At x = 0, y = 3 − 4/5 = 11/5. 11/2 is the size of the x-intercept, not the y-intercept.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक रेखा (2, 3) से गुजरती है और 2x − 5y + 7 = 0 के समांतर है। उसका y-अंतःखंड क्या है?","optionsHi":["−11/5","3/5","11/5","11/2"],"explanationHi":"समांतर रेखा की ढाल 2/5 है: y − 3 = (2/5)(x − 2)। x = 0 पर y = 3 − 4/5 = 11/5। 11/2 x-अंतःखंड का परिमाण है, y-अंतःखंड का नहीं।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-95","question":"If x = 3 + 2√2, what is the value of x³ + 1/x³?","options":["216","204","194","198"],"answer":3,"explanation":"1/x = 3 − 2√2 (rationalise), so x + 1/x = 6. Then x³ + 1/x³ = 6³ − 3 × 6 = 216 − 18 = 198.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि x = 3 + 2√2 है, तो x³ + 1/x³ का मान क्या है?","optionsHi":["216","204","194","198"],"explanationHi":"1/x = 3 − 2√2 (परिमेयीकरण से), अतः x + 1/x = 6। तब x³ + 1/x³ = 6³ − 3 × 6 = 216 − 18 = 198।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-96","question":"If a + b + c = 15 and a² + b² + c² = 83, what is the value of a³ + b³ + c³ − 3abc?","options":["180","225","1245","150"],"answer":0,"explanation":"ab + bc + ca = (15² − 83)/2 = 71. a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) = 15 × (83 − 71) = 180.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि a + b + c = 15 और a² + b² + c² = 83 है, तो a³ + b³ + c³ − 3abc का मान क्या है?","optionsHi":["180","225","1245","150"],"explanationHi":"ab + bc + ca = (15² − 83)/2 = 71। a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) = 15 × (83 − 71) = 180।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-97","question":"If x, y and z are real numbers such that x² + y² + z² = 2(x − 2y + 3z) − 14, what is the value of x + y + z?","options":["6","2","0","4"],"answer":1,"explanation":"Rearranging: (x − 1)² + (y + 2)² + (z − 3)² = 1 + 4 + 9 − 14 = 0. A sum of squares is zero only if each is zero, so x = 1, y = −2, z = 3 and x + y + z = 2.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि x, y और z ऐसी वास्तविक संख्याएँ हैं कि x² + y² + z² = 2(x − 2y + 3z) − 14 है, तो x + y + z का मान क्या है?","optionsHi":["6","2","0","4"],"explanationHi":"पुनर्व्यवस्थित करने पर: (x − 1)² + (y + 2)² + (z − 3)² = 1 + 4 + 9 − 14 = 0। वर्गों का योग शून्य तभी होता है जब प्रत्येक शून्य हो, अतः x = 1, y = −2, z = 3 और x + y + z = 2।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-98","question":"If 3x + 1/(2x) = 5, what is the value of 4x² + 1/(9x²)?","options":["25","76/9","88/9","100/9"],"answer":2,"explanation":"Multiply by 2/3: 2x + 1/(3x) = 10/3. Squaring, 4x² + 1/(9x²) + 2 × 2x × 1/(3x) = 100/9, so 4x² + 1/(9x²) = 100/9 − 4/3 = 88/9.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि 3x + 1/(2x) = 5 है, तो 4x² + 1/(9x²) का मान क्या है?","optionsHi":["25","76/9","88/9","100/9"],"explanationHi":"2/3 से गुणा करने पर: 2x + 1/(3x) = 10/3। वर्ग करने पर 4x² + 1/(9x²) + 2 × 2x × 1/(3x) = 100/9, अतः 4x² + 1/(9x²) = 100/9 − 4/3 = 88/9।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-99","question":"If tan θ = 8/15, what is the value of (2 sin θ − cos θ)/(sin θ + 2 cos θ)?","options":["1/19","31/38","8/19","1/38"],"answer":3,"explanation":"Divide top and bottom by cos θ: (2 tan θ − 1)/(tan θ + 2) = (16/15 − 1)/(8/15 + 2) = (1/15)/(38/15) = 1/38.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि tan θ = 8/15 है, तो (2 sin θ − cos θ)/(sin θ + 2 cos θ) का मान क्या है?","optionsHi":["1/19","31/38","8/19","1/38"],"explanationHi":"अंश और हर को cos θ से भाग देने पर: (2 tan θ − 1)/(tan θ + 2) = (16/15 − 1)/(8/15 + 2) = (1/15)/(38/15) = 1/38।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-100","question":"In triangle ABC, AB = 10 cm, AC = 14 cm and BC = 16 cm. What is the length of the median AD?","options":["2√21 cm","4√6 cm","2√37 cm","12 cm"],"answer":0,"explanation":"Apollonius: AB² + AC² = 2(AD² + BD²), so 296 = 2(AD² + 64) and AD² = 84. AD = √84 = 2√21 cm.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"त्रिभुज ABC में AB = 10 cm, AC = 14 cm और BC = 16 cm है। माध्यिका AD की लंबाई कितनी है?","optionsHi":["2√21 cm","4√6 cm","2√37 cm","12 cm"],"explanationHi":"अपोलोनियस प्रमेय: AB² + AC² = 2(AD² + BD²), अतः 296 = 2(AD² + 64) और AD² = 84। AD = √84 = 2√21 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-101","question":"Chords AB and CD of a circle intersect at a point P inside it. If AP = 6 cm, PB = 4 cm and CP = 3 cm, what is the length of CD?","options":["8 cm","11 cm","13 cm","10 cm"],"answer":1,"explanation":"Intersecting chords: AP × PB = CP × PD, so PD = 24/3 = 8 cm and CD = 3 + 8 = 11 cm. 8 cm is only PD.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक वृत्त की जीवाएँ AB और CD उसके अंदर बिंदु P पर काटती हैं। यदि AP = 6 cm, PB = 4 cm और CP = 3 cm है, तो CD की लंबाई कितनी है?","optionsHi":["8 cm","11 cm","13 cm","10 cm"],"explanationHi":"प्रतिच्छेदी जीवाएँ: AP × PB = CP × PD, अतः PD = 24/3 = 8 cm और CD = 3 + 8 = 11 cm। 8 cm केवल PD है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-102","question":"The incircle of triangle ABC, with AB = 13 cm, BC = 14 cm and CA = 15 cm, touches BC at D. What is BD?","options":["7 cm","8 cm","6 cm","5 cm"],"answer":2,"explanation":"With s = 21, the tangent length from B is BD = s − CA = 21 − 15 = 6 cm (and CD = s − AB = 8 cm). 7 cm assumes D is the midpoint.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"त्रिभुज ABC का अंतःवृत्त, जिसमें AB = 13 cm, BC = 14 cm और CA = 15 cm है, BC को D पर स्पर्श करता है। BD कितना है?","optionsHi":["7 cm","8 cm","6 cm","5 cm"],"explanationHi":"s = 21 के साथ, B से स्पर्श रेखा की लंबाई BD = s − CA = 21 − 15 = 6 cm (और CD = s − AB = 8 cm)। 7 cm तब आता है जब D को मध्य बिंदु मान लिया जाए।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-103","question":"Two points P and Q lie on opposite sides of a tower, in line with its foot, and are 40(3 + √3) m apart. The angles of elevation of the top of the tower from P and Q are 45° and 60°. What is the height of the tower?","options":["40√3 m","60(√3 + 1) m","80 m","120 m"],"answer":3,"explanation":"h + h/√3 = 40(3 + √3). Since 3 + √3 = √3(√3 + 1), h(√3 + 1)/√3 = 40√3(√3 + 1), giving h = 40 × 3 = 120 m.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"दो बिंदु P और Q एक मीनार के विपरीत ओर, उसके आधार के साथ एक ही सरल रेखा में स्थित हैं और उनके बीच की दूरी 40(3 + √3) m है। P और Q से मीनार के शीर्ष के उन्नयन कोण 45° और 60° हैं। मीनार की ऊँचाई कितनी है?","optionsHi":["40√3 m","60(√3 + 1) m","80 m","120 m"],"explanationHi":"h + h/√3 = 40(3 + √3)। चूँकि 3 + √3 = √3(√3 + 1), h(√3 + 1)/√3 = 40√3(√3 + 1), जिससे h = 40 × 3 = 120 m।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-104","question":"If cos θ/(1 − sin θ) + cos θ/(1 + sin θ) = 4 and θ is acute, what is θ?","options":["60°","30°","45°","75°"],"answer":0,"explanation":"The left side = cos θ × 2/(1 − sin²θ) = 2/cos θ = 2 sec θ. So sec θ = 2 and θ = 60°.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि cos θ/(1 − sin θ) + cos θ/(1 + sin θ) = 4 है और θ न्यूनकोण है, तो θ क्या है?","optionsHi":["60°","30°","45°","75°"],"explanationHi":"बायाँ पक्ष = cos θ × 2/(1 − sin²θ) = 2/cos θ = 2 sec θ। अतः sec θ = 2 और θ = 60°।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-105","question":"The roots of x² − 9x + k = 0 differ by 3. What is the value of k?","options":["20","18","14","27"],"answer":1,"explanation":"(α − β)² = (α + β)² − 4αβ, so 9 = 81 − 4k and k = 18 (roots 6 and 3). 27 wrongly takes 3 × 9.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"समीकरण x² − 9x + k = 0 के मूलों का अंतर 3 है। k का मान क्या है?","optionsHi":["20","18","14","27"],"explanationHi":"(α − β)² = (α + β)² − 4αβ, अतः 9 = 81 − 4k और k = 18 (मूल 6 और 3)। 27 में गलती से 3 × 9 ले लिया गया है।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-106","question":"AB is a diameter of a circle and C is a point on the circle with ∠CAB = 28°. The tangent at C meets AB produced beyond B at T. What is ∠CTA?","options":["28°","62°","34°","56°"],"answer":2,"explanation":"∠ACB = 90°, so ∠ABC = 62° and ∠CBT = 118°. By the alternate segment theorem ∠TCB = ∠CAB = 28°. In triangle CBT, ∠CTB = 180° − 118° − 28° = 34°.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"AB एक वृत्त का व्यास है और C वृत्त पर एक बिंदु है जिसमें ∠CAB = 28° है। C पर स्पर्श रेखा, बढ़ाई गई AB को B के आगे T पर मिलती है। ∠CTA कितना है?","optionsHi":["28°","62°","34°","56°"],"explanationHi":"∠ACB = 90°, अतः ∠ABC = 62° और ∠CBT = 118°। एकांतर वृत्तखंड प्रमेय से ∠TCB = ∠CAB = 28°। त्रिभुज CBT में ∠CTB = 180° − 118° − 28° = 34°।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-107","question":"If sec²θ + tan²θ = 7/3, what is the value of sec⁴θ − tan⁴θ?","options":["1","49/9","4/3","7/3"],"answer":3,"explanation":"sec⁴θ − tan⁴θ = (sec²θ − tan²θ)(sec²θ + tan²θ) = 1 × 7/3 = 7/3. No need to find θ.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि sec²θ + tan²θ = 7/3 है, तो sec⁴θ − tan⁴θ का मान क्या है?","optionsHi":["1","49/9","4/3","7/3"],"explanationHi":"sec⁴θ − tan⁴θ = (sec²θ − tan²θ)(sec²θ + tan²θ) = 1 × 7/3 = 7/3। θ ज्ञात करने की आवश्यकता नहीं है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-108","question":"For what value of k are the lines 3x + 2ky − 2 = 0 and 2x + 5y + 1 = 0 parallel?","options":["15/4","4/15","5/3","−15/4"],"answer":0,"explanation":"Parallel lines need a₁/a₂ = b₁/b₂: 3/2 = 2k/5, so 4k = 15 and k = 15/4. 4/15 inverts the ratio, and −15/4 wrongly brings in a sign that the proportion does not have.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"k के किस मान के लिए रेखाएँ 3x + 2ky − 2 = 0 और 2x + 5y + 1 = 0 समांतर हैं?","optionsHi":["15/4","4/15","5/3","−15/4"],"explanationHi":"समांतर रेखाओं के लिए a₁/a₂ = b₁/b₂: 3/2 = 2k/5, अतः 4k = 15 और k = 15/4। 4/15 में अनुपात उलट गया है, और −15/4 में गलती से ऐसा चिह्न आ गया है जो अनुपात में है ही नहीं।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-109","question":"If x = ∛(2 + √3) + ∛(2 − √3), what is the value of x³ − 3x?","options":["2","4","1","3√3"],"answer":1,"explanation":"Let p and q be the two cube roots, so pq = ∛(4 − 3) = 1. Then x³ = p³ + q³ + 3pq(p + q) = 4 + 3x, so x³ − 3x = 4.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि x = ∛(2 + √3) + ∛(2 − √3) है, तो x³ − 3x का मान क्या है?","optionsHi":["2","4","1","3√3"],"explanationHi":"माना p और q दोनों घनमूल हैं, अतः pq = ∛(4 − 3) = 1। तब x³ = p³ + q³ + 3pq(p + q) = 4 + 3x, अतः x³ − 3x = 4।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-110","question":"If a + b + c = 0, what is the value of (a + b)(b + c)(c + a) + abc?","options":["abc","2abc","0","−2abc"],"answer":2,"explanation":"a + b = −c, b + c = −a and c + a = −b, so the product is (−c)(−a)(−b) = −abc. Adding abc gives 0. 2abc forgets the sign.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि a + b + c = 0 है, तो (a + b)(b + c)(c + a) + abc का मान क्या है?","optionsHi":["abc","2abc","0","−2abc"],"explanationHi":"a + b = −c, b + c = −a और c + a = −b, अतः गुणनफल (−c)(−a)(−b) = −abc है। abc जोड़ने पर 0 आता है। 2abc में चिह्न छूट गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-111","question":"If x = 99, what is the value of x(x² + 3x + 3)?","options":["10,00,000","9,99,997","9,70,299","9,99,999"],"answer":3,"explanation":"x³ + 3x² + 3x = (x + 1)³ − 1 = 100³ − 1 = 9,99,999. Spotting the incomplete cube avoids the long multiplication.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि x = 99 है, तो x(x² + 3x + 3) का मान क्या है?","optionsHi":["10,00,000","9,99,997","9,70,299","9,99,999"],"explanationHi":"x³ + 3x² + 3x = (x + 1)³ − 1 = 100³ − 1 = 9,99,999। अपूर्ण घन को पहचानने से लंबे गुणन से बचा जा सकता है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-112","question":"If x⁴ + 1/x⁴ = 322 and x > 1, what is the value of x³ − 1/x³?","options":["76","64","52","80"],"answer":0,"explanation":"x² + 1/x² = √(322 + 2) = 18, so (x − 1/x)² = 16 and x − 1/x = 4. Then x³ − 1/x³ = 4³ + 3 × 4 = 76. 52 subtracts 3 × 4 instead of adding.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि x⁴ + 1/x⁴ = 322 और x > 1 है, तो x³ − 1/x³ का मान क्या है?","optionsHi":["76","64","52","80"],"explanationHi":"x² + 1/x² = √(322 + 2) = 18, अतः (x − 1/x)² = 16 और x − 1/x = 4। तब x³ − 1/x³ = 4³ + 3 × 4 = 76। 52 में 3 × 4 को जोड़ने के बजाय घटा दिया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-113","question":"What is the minimum value of 4 sec²θ + 9 cos²θ?","options":["13","12","6","36"],"answer":1,"explanation":"With c = cos²θ, AM ≥ GM gives 4/c + 9c ≥ 2√36 = 12, with equality at c = 2/3, which is allowed. 13 is the trap of putting θ = 0°.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"4 sec²θ + 9 cos²θ का न्यूनतम मान क्या है?","optionsHi":["13","12","6","36"],"explanationHi":"c = cos²θ लेने पर AM ≥ GM से 4/c + 9c ≥ 2√36 = 12, जिसमें समता c = 2/3 पर होती है, जो मान्य है। 13 वह जाल है जो θ = 0° रखने से मिलता है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-114","question":"If sin(A + B) = 1 and cos(A − B) = √3/2, where 0° < B < A < 90°, what is the value of cos(2A + B)?","options":["√3/2","−1/2","−√3/2","0"],"answer":2,"explanation":"A + B = 90° and A − B = 30° give A = 60°, B = 30°. cos(150°) = −cos 30° = −√3/2. The sign trap gives √3/2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि sin(A + B) = 1 और cos(A − B) = √3/2 है, जहाँ 0° < B < A < 90° है, तो cos(2A + B) का मान क्या है?","optionsHi":["√3/2","−1/2","−√3/2","0"],"explanationHi":"A + B = 90° और A − B = 30° से A = 60°, B = 30°। cos(150°) = −cos 30° = −√3/2। चिह्न की गलती से √3/2 आता है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-115","question":"In triangle ABC, AB = AC and ∠BAC = 40°. D is a point on AC such that BD = BC. What is ∠ABD?","options":["40°","20°","35°","30°"],"answer":3,"explanation":"Base angles are 70° each. In isosceles triangle BDC, ∠BDC = ∠BCD = 70°, so ∠DBC = 40°. ∠ABD = 70° − 40° = 30°.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"त्रिभुज ABC में AB = AC और ∠BAC = 40° है। D, AC पर ऐसा बिंदु है कि BD = BC है। ∠ABD कितना है?","optionsHi":["40°","20°","35°","30°"],"explanationHi":"आधार कोण प्रत्येक 70° हैं। समद्विबाहु त्रिभुज BDC में ∠BDC = ∠BCD = 70°, अतः ∠DBC = 40°। ∠ABD = 70° − 40° = 30°।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-116","question":"Two circles of radii 10 cm and 17 cm intersect, and their common chord is 16 cm long. What is the distance between their centres?","options":["21 cm","9 cm","27 cm","24 cm"],"answer":0,"explanation":"The line of centres bisects the common chord at right angles: distances from the centres are √(100 − 64) = 6 and √(289 − 64) = 15. The centres lie on opposite sides of the chord, so the distance is 21 cm; 9 cm wrongly puts them on the same side.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"10 cm और 17 cm त्रिज्या वाले दो वृत्त एक-दूसरे को काटते हैं और उनकी उभयनिष्ठ जीवा 16 cm लंबी है। उनके केंद्रों के बीच की दूरी कितनी है?","optionsHi":["21 cm","9 cm","27 cm","24 cm"],"explanationHi":"केंद्रों को मिलाने वाली रेखा उभयनिष्ठ जीवा को समकोण पर समद्विभाजित करती है: केंद्रों से दूरियाँ √(100 − 64) = 6 और √(289 − 64) = 15 हैं। केंद्र जीवा के विपरीत ओर हैं, अतः दूरी 21 cm है; 9 cm में उन्हें गलती से एक ही ओर मान लिया गया है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-117","question":"In triangle ABC, ∠A = 90° and AD is perpendicular to BC. If BD = 9 cm and DC = 16 cm, what is the area of triangle ABD?","options":["150 cm²","54 cm²","96 cm²","108 cm²"],"answer":1,"explanation":"AD² = BD × DC = 144, so AD = 12 cm. Area of ABD = ½ × 9 × 12 = 54 cm². 150 cm² is the whole triangle and 96 cm² is ADC.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"त्रिभुज ABC में ∠A = 90° है और AD, BC पर लंब है। यदि BD = 9 cm और DC = 16 cm है, तो त्रिभुज ABD का क्षेत्रफल कितना है?","optionsHi":["150 cm²","54 cm²","96 cm²","108 cm²"],"explanationHi":"AD² = BD × DC = 144, अतः AD = 12 cm। ABD का क्षेत्रफल = ½ × 9 × 12 = 54 cm²। 150 cm² पूरे त्रिभुज का क्षेत्रफल है और 96 cm² ADC का।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-118","question":"For how many values of k does x² − (k + 3)x + 4k = 0 have equal roots, and what is the sum of those values?","options":["1 value, sum 9","2 values, sum 9","2 values, sum 10","2 values, sum −10"],"answer":2,"explanation":"Equal roots need (k + 3)² = 16k, i.e. k² − 10k + 9 = 0, so k = 1 or 9: two values with sum 10 (the sum of roots of the quadratic in k).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"k के कितने मानों के लिए x² − (k + 3)x + 4k = 0 के मूल बराबर होंगे, और उन मानों का योग क्या है?","optionsHi":["1 मान, योग 9","2 मान, योग 9","2 मान, योग 10","2 मान, योग −10"],"explanationHi":"बराबर मूलों के लिए (k + 3)² = 16k, अर्थात k² − 10k + 9 = 0, अतः k = 1 या 9: दो मान जिनका योग 10 है (k में द्विघात के मूलों का योग)।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-119","question":"The triangle with vertices (1, 2), (5, 6) and (k, −2) has an area of 12 square units. What is the sum of all possible values of k?","options":["3","−9","6","−6"],"answer":3,"explanation":"Area = ½|1(6 + 2) + 5(−2 − 2) + k(2 − 6)| = ½|−12 − 4k| = 12, so |12 + 4k| = 24, giving k = 3 or −9. Sum = −6.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"शीर्षों (1, 2), (5, 6) और (k, −2) वाले त्रिभुज का क्षेत्रफल 12 वर्ग इकाई है। k के सभी संभावित मानों का योग क्या है?","optionsHi":["3","−9","6","−6"],"explanationHi":"क्षेत्रफल = ½|1(6 + 2) + 5(−2 − 2) + k(2 − 6)| = ½|−12 − 4k| = 12, अतः |12 + 4k| = 24, जिससे k = 3 या −9। योग = −6।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-120","question":"If sin⁴θ − cos⁴θ = 1/3, what is the value of tan²θ?","options":["2","1/2","3","4/3"],"answer":0,"explanation":"sin⁴θ − cos⁴θ = (sin²θ − cos²θ)(sin²θ + cos²θ) = sin²θ − cos²θ = 1/3. With sin²θ + cos²θ = 1, sin²θ = 2/3 and cos²θ = 1/3, so tan²θ = 2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि sin⁴θ − cos⁴θ = 1/3 है, तो tan²θ का मान क्या है?","optionsHi":["2","1/2","3","4/3"],"explanationHi":"sin⁴θ − cos⁴θ = (sin²θ − cos²θ)(sin²θ + cos²θ) = sin²θ − cos²θ = 1/3। sin²θ + cos²θ = 1 के साथ sin²θ = 2/3 और cos²θ = 1/3, अतः tan²θ = 2।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-121","question":"What is the value of cos 60° × sec 60° + tan 45°?","options":["1","2","3","0"],"answer":1,"explanation":"cos 60° × sec 60° = 1 (reciprocals), and tan 45° = 1, so the value is 2.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"cos 60° × sec 60° + tan 45° का मान क्या है?","optionsHi":["1","2","3","0"],"explanationHi":"cos 60° × sec 60° = 1 (व्युत्क्रम), और tan 45° = 1, अतः मान 2 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-122","question":"What is the sum of the exterior angles of a regular decagon?","options":["1,440°","144°","360°","180°"],"answer":2,"explanation":"The exterior angles of any convex polygon add up to 360°. 1,440° is the sum of the interior angles and 144° is one interior angle.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक सम दशभुज के बाह्य कोणों का योग कितना है?","optionsHi":["1,440°","144°","360°","180°"],"explanationHi":"किसी भी उत्तल बहुभुज के बाह्य कोणों का योग 360° होता है। 1,440° आंतरिक कोणों का योग है और 144° एक आंतरिक कोण है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-123","question":"What is the slope of the line passing through (1, 2) and (4, 11)?","options":["1/3","−3","9","3"],"answer":3,"explanation":"Slope = (y₂ − y₁)/(x₂ − x₁) = 9/3 = 3. 1/3 inverts the formula.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"बिंदुओं (1, 2) और (4, 11) से गुजरने वाली रेखा की ढाल क्या है?","optionsHi":["1/3","−3","9","3"],"explanationHi":"ढाल = (y₂ − y₁)/(x₂ − x₁) = 9/3 = 3। 1/3 में सूत्र उलट दिया गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-124","question":"If 5x − 3 = 2x + 9, what is the value of x² − 1?","options":["15","16","8","24"],"answer":0,"explanation":"3x = 12, so x = 4 and x² − 1 = 15. 16 forgets to subtract 1.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"यदि 5x − 3 = 2x + 9 है, तो x² − 1 का मान क्या है?","optionsHi":["15","16","8","24"],"explanationHi":"3x = 12, अतः x = 4 और x² − 1 = 15। 16 में 1 घटाना भूल गए।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-125","question":"If x + y = 12 and xy = 32, what is the value of x² + y²?","options":["112","80","144","64"],"answer":1,"explanation":"x² + y² = (x + y)² − 2xy = 144 − 64 = 80. 112 adds 2xy instead of subtracting.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि x + y = 12 और xy = 32 है, तो x² + y² का मान क्या है?","optionsHi":["112","80","144","64"],"explanationHi":"x² + y² = (x + y)² − 2xy = 144 − 64 = 80। 112 में 2xy को घटाने के बजाय जोड़ दिया गया है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-126","question":"If a − b = 2 and b − c = 3, what is the value of (a − b)³ + (b − c)³ + (c − a)³?","options":["90","160","−90","−160"],"answer":2,"explanation":"The three brackets add up to 0, so the sum of cubes = 3(a − b)(b − c)(c − a) = 3 × 2 × 3 × (−5) = −90.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि a − b = 2 और b − c = 3 है, तो (a − b)³ + (b − c)³ + (c − a)³ का मान क्या है?","optionsHi":["90","160","−90","−160"],"explanationHi":"तीनों कोष्ठकों का योग 0 है, अतः घनों का योग = 3(a − b)(b − c)(c − a) = 3 × 2 × 3 × (−5) = −90।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-127","question":"The angles A, B and C of a triangle are in the ratio 1 : 2 : 3. What is the ratio of the sides opposite them?","options":["1 : 2 : 3","1 : √2 : √3","√3 : 1 : 2","1 : √3 : 2"],"answer":3,"explanation":"The angles are 30°, 60° and 90°, and sides are proportional to the sines: 1/2 : √3/2 : 1 = 1 : √3 : 2. Sides are not in the ratio of the angles.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक त्रिभुज के कोण A, B और C का अनुपात 1 : 2 : 3 है। उनके सम्मुख भुजाओं का अनुपात क्या है?","optionsHi":["1 : 2 : 3","1 : √2 : √3","√3 : 1 : 2","1 : √3 : 2"],"explanationHi":"कोण 30°, 60° और 90° हैं, और भुजाएँ ज्याओं (sine) के अनुपात में होती हैं: 1/2 : √3/2 : 1 = 1 : √3 : 2। भुजाएँ कोणों के अनुपात में नहीं होतीं।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-128","question":"What is the distance between the parallel lines 3x + 4y = 7 and 3x + 4y = 22?","options":["3","15","5","29/5"],"answer":0,"explanation":"With the same 3x + 4y, distance = |c₁ − c₂|/√(a² + b²) = |22 − 7|/5 = 3. 15 forgets to divide by √(9 + 16) = 5, and 29/5 adds the constants instead of subtracting them.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"समांतर रेखाओं 3x + 4y = 7 और 3x + 4y = 22 के बीच की दूरी क्या है?","optionsHi":["3","15","5","29/5"],"explanationHi":"3x + 4y समान होने पर दूरी = |c₁ − c₂|/√(a² + b²) = |22 − 7|/5 = 3। 15 में √(9 + 16) = 5 से भाग देना भूल गए, और 29/5 में अचर पदों को घटाने के बजाय जोड़ दिया गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-129","question":"If sin θ = 3/5 and θ is acute, what is the value of tan θ + sec θ?","options":["7/4","2","8/5","3/2"],"answer":1,"explanation":"cos θ = 4/5, so tan θ = 3/4 and sec θ = 5/4. Their sum is 8/4 = 2.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि sin θ = 3/5 है और θ न्यूनकोण है, तो tan θ + sec θ का मान क्या है?","optionsHi":["7/4","2","8/5","3/2"],"explanationHi":"cos θ = 4/5, अतः tan θ = 3/4 और sec θ = 5/4। इनका योग 8/4 = 2 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-130","question":"If 2ˣ⁺³ = 32ˣ⁻¹, what is the value of x?","options":["1","3","2","4"],"answer":2,"explanation":"32 = 2⁵, so x + 3 = 5(x − 1) = 5x − 5, giving 4x = 8 and x = 2.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि 2ˣ⁺³ = 32ˣ⁻¹ है, तो x का मान क्या है?","optionsHi":["1","3","2","4"],"explanationHi":"32 = 2⁵, अतः x + 3 = 5(x − 1) = 5x − 5, जिससे 4x = 8 और x = 2।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-131","question":"What is the area of the triangle with vertices (0, 0), (6, 0) and (3, 4)?","options":["24 sq units","10 sq units","15 sq units","12 sq units"],"answer":3,"explanation":"The base on the x-axis is 6 and the height is the y-coordinate 4, so area = ½ × 6 × 4 = 12. 24 forgets the ½.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"शीर्षों (0, 0), (6, 0) और (3, 4) वाले त्रिभुज का क्षेत्रफल क्या है?","optionsHi":["24 वर्ग इकाई","10 वर्ग इकाई","15 वर्ग इकाई","12 वर्ग इकाई"],"explanationHi":"x-अक्ष पर आधार 6 है और ऊँचाई y-निर्देशांक 4 है, अतः क्षेत्रफल = ½ × 6 × 4 = 12। 24 में ½ छूट गया है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-132","question":"A chord of length 24 cm is drawn in a circle of radius 13 cm. How far is the chord from the centre?","options":["5 cm","12 cm","7 cm","11 cm"],"answer":0,"explanation":"The perpendicular from the centre bisects the chord: d = √(13² − 12²) = 5 cm. Using the full chord length 24 is the usual slip.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"13 cm त्रिज्या वाले वृत्त में 24 cm लंबी जीवा खींची गई है। जीवा केंद्र से कितनी दूर है?","optionsHi":["5 cm","12 cm","7 cm","11 cm"],"explanationHi":"केंद्र से डाला गया लंब जीवा को समद्विभाजित करता है: d = √(13² − 12²) = 5 cm। जीवा की पूरी लंबाई 24 लेना आम भूल है।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-133","question":"If x = 1/(3 − 2√2) and y = 1/(3 + 2√2), what is the value of x² + y² − xy?","options":["34","33","35","36"],"answer":1,"explanation":"x = 3 + 2√2 and y = 3 − 2√2, so x + y = 6 and xy = 1. x² + y² − xy = (x + y)² − 3xy = 36 − 3 = 33.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि x = 1/(3 − 2√2) और y = 1/(3 + 2√2) है, तो x² + y² − xy का मान क्या है?","optionsHi":["34","33","35","36"],"explanationHi":"x = 3 + 2√2 और y = 3 − 2√2, अतः x + y = 6 और xy = 1। x² + y² − xy = (x + y)² − 3xy = 36 − 3 = 33।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-134","question":"If a + b = 1 and a³ + b³ = 19, what is the value of ab?","options":["6","−18","−6","18"],"answer":2,"explanation":"a³ + b³ = (a + b)³ − 3ab(a + b) = 1 − 3ab = 19, so ab = −6. (a and b are 3 and −2.)","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि a + b = 1 और a³ + b³ = 19 है, तो ab का मान क्या है?","optionsHi":["6","−18","−6","18"],"explanationHi":"a³ + b³ = (a + b)³ − 3ab(a + b) = 1 − 3ab = 19, अतः ab = −6। (a और b क्रमशः 3 और −2 हैं।)","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-135","question":"What is the value of √(12 + √(12 + √(12 + …))) continued forever?","options":["3","2√3","6","4"],"answer":3,"explanation":"Let x be the value: x = √(12 + x), so x² − x − 12 = 0 and x = 4 (the root −3 is rejected). Trick: the answer is n + 1 when 12 = n(n + 1).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"√(12 + √(12 + √(12 + …))) का मान, अनंत तक जारी रखने पर, क्या है?","optionsHi":["3","2√3","6","4"],"explanationHi":"मान x मानें: x = √(12 + x), अतः x² − x − 12 = 0 और x = 4 (मूल −3 अस्वीकार्य है)। शॉर्टकट: जब 12 = n(n + 1) हो, तो उत्तर n + 1 होता है।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-136","question":"What is the value of tan 15° + cot 15°?","options":["4","2√3","2","√3 + 1"],"answer":0,"explanation":"tan 15° = 2 − √3 and cot 15° = 2 + √3, so the sum is 4. Alternatively tan θ + cot θ = 2/sin 2θ = 2/sin 30° = 4.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"tan 15° + cot 15° का मान क्या है?","optionsHi":["4","2√3","2","√3 + 1"],"explanationHi":"tan 15° = 2 − √3 और cot 15° = 2 + √3, अतः योगफल 4 है। वैकल्पिक रूप से tan θ + cot θ = 2/sin 2θ = 2/sin 30° = 4।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-137","question":"What is the value of sin 75°?","options":["(√6 − √2)/4","(√6 + √2)/4","(√3 + 1)/2","√3/2"],"answer":1,"explanation":"sin(45° + 30°) = sin 45° cos 30° + cos 45° sin 30° = (√3 + 1)/(2√2) = (√6 + √2)/4. The minus version is sin 15°.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"sin 75° का मान क्या है?","optionsHi":["(√6 − √2)/4","(√6 + √2)/4","(√3 + 1)/2","√3/2"],"explanationHi":"sin(45° + 30°) = sin 45° cos 30° + cos 45° sin 30° = (√3 + 1)/(2√2) = (√6 + √2)/4। ऋण वाला रूप sin 15° का है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-138","question":"Two circles of radii 9 cm and 4 cm touch each other externally. What is the length of their direct common tangent?","options":["13 cm","5 cm","12 cm","6 cm"],"answer":2,"explanation":"The centres are 9 + 4 = 13 cm apart, so the tangent = √(13² − (9 − 4)²) = 12 cm. Shortcut for touching circles: 2√(r₁r₂) = 2√36 = 12.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"9 cm और 4 cm त्रिज्या वाले दो वृत्त एक-दूसरे को बाह्य रूप से स्पर्श करते हैं। उनकी उभयनिष्ठ बाह्य स्पर्श रेखा की लंबाई कितनी है?","optionsHi":["13 cm","5 cm","12 cm","6 cm"],"explanationHi":"केंद्रों के बीच की दूरी 9 + 4 = 13 cm है, अतः स्पर्श रेखा = √(13² − (9 − 4)²) = 12 cm। स्पर्श करते वृत्तों के लिए शॉर्टकट: 2√(r₁r₂) = 2√36 = 12।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-139","question":"The interior and exterior angles of a regular polygon are in the ratio 7 : 2. How many sides does the polygon have?","options":["7","10","12","9"],"answer":3,"explanation":"Exterior = 180° × 2/9 = 40°, so n = 360/40 = 9. Quick rule: interior/exterior = (n − 2)/2 = 7/2 gives n = 9.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक सम बहुभुज के आंतरिक और बाह्य कोणों का अनुपात 7 : 2 है। बहुभुज की कितनी भुजाएँ हैं?","optionsHi":["7","10","12","9"],"explanationHi":"बाह्य कोण = 180° × 2/9 = 40°, अतः n = 360/40 = 9। त्वरित नियम: आंतरिक/बाह्य = (n − 2)/2 = 7/2 से n = 9।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-140","question":"D and E are the midpoints of sides AB and AC of triangle ABC. What is the ratio of the area of triangle ADE to the area of the quadrilateral DBCE?","options":["1 : 3","1 : 4","1 : 2","1 : 1"],"answer":0,"explanation":"Triangle ADE is similar to ABC with ratio 1/2, so its area is 1/4 of ABC. The trapezium is the remaining 3/4, giving 1 : 3. 1 : 4 compares ADE with the whole triangle.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"D और E त्रिभुज ABC की भुजाओं AB और AC के मध्य बिंदु हैं। त्रिभुज ADE और चतुर्भुज DBCE के क्षेत्रफलों का अनुपात क्या है?","optionsHi":["1 : 3","1 : 4","1 : 2","1 : 1"],"explanationHi":"त्रिभुज ADE, ABC के समरूप है जिसका अनुपात 1/2 है, अतः इसका क्षेत्रफल ABC का 1/4 है। समलंब चतुर्भुज शेष 3/4 है, जिससे अनुपात 1 : 3 आता है। 1 : 4 में ADE की तुलना पूरे त्रिभुज से की गई है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-141","question":"If cot θ = 7/8, what is the value of (1 + sin θ)(1 − sin θ)/[(1 + cos θ)(1 − cos θ)]?","options":["64/49","49/64","7/8","15/64"],"answer":1,"explanation":"The expression is (1 − sin²θ)/(1 − cos²θ) = cos²θ/sin²θ = cot²θ = 49/64.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि cot θ = 7/8 है, तो (1 + sin θ)(1 − sin θ)/[(1 + cos θ)(1 − cos θ)] का मान क्या है?","optionsHi":["64/49","49/64","7/8","15/64"],"explanationHi":"व्यंजक (1 − sin²θ)/(1 − cos²θ) = cos²θ/sin²θ = cot²θ = 49/64 है।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-142","question":"The line 2x + 3y = 12 meets the x-axis at A and the y-axis at B. What is the length of AB?","options":["√13","10","2√13","13"],"answer":2,"explanation":"A = (6, 0) and B = (0, 4). AB = √(36 + 16) = √52 = 2√13 units.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"रेखा 2x + 3y = 12 x-अक्ष को A पर और y-अक्ष को B पर मिलती है। AB की लंबाई क्या है?","optionsHi":["√13","10","2√13","13"],"explanationHi":"A = (6, 0) और B = (0, 4)। AB = √(36 + 16) = √52 = 2√13 इकाई।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-143","question":"If x² − 4x + 1 = 0, what is the value of x⁴ + 1/x⁴?","options":["196","192","14","194"],"answer":3,"explanation":"Dividing by x: x + 1/x = 4. Then x² + 1/x² = 16 − 2 = 14 and x⁴ + 1/x⁴ = 196 − 2 = 194.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि x² − 4x + 1 = 0 है, तो x⁴ + 1/x⁴ का मान क्या है?","optionsHi":["196","192","14","194"],"explanationHi":"x से भाग देने पर: x + 1/x = 4। तब x² + 1/x² = 16 − 2 = 14 और x⁴ + 1/x⁴ = 196 − 2 = 194।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-144","question":"If 1/a + 1/b + 1/c = 0 and a + b + c = 9, what is the value of a² + b² + c²?","options":["81","9","27","0"],"answer":0,"explanation":"1/a + 1/b + 1/c = (ab + bc + ca)/abc = 0, so ab + bc + ca = 0. Then a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि 1/a + 1/b + 1/c = 0 और a + b + c = 9 है, तो a² + b² + c² का मान क्या है?","optionsHi":["81","9","27","0"],"explanationHi":"1/a + 1/b + 1/c = (ab + bc + ca)/abc = 0, अतः ab + bc + ca = 0। तब a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-145","question":"If x = 2 − ∛2 + ∛4, what is the value of x³ − 6x² + 18x?","options":["18","22","24","40"],"answer":1,"explanation":"With t = ∛2, (x − 2) = t² − t, and cubing gives (x − 2)³ = t⁶ − 3t⁵ + 3t⁴ − t³ = 4 − 6t² + 6t − 2 = 2 − 6(t² − t) = 2 − 6(x − 2). Expanding: x³ − 6x² + 12x − 8 = 14 − 6x, so x³ − 6x² + 18x = 22.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि x = 2 − ∛2 + ∛4 है, तो x³ − 6x² + 18x का मान क्या है?","optionsHi":["18","22","24","40"],"explanationHi":"t = ∛2 लेने पर (x − 2) = t² − t, और घन करने पर (x − 2)³ = t⁶ − 3t⁵ + 3t⁴ − t³ = 4 − 6t² + 6t − 2 = 2 − 6(t² − t) = 2 − 6(x − 2)। प्रसार करने पर: x³ − 6x² + 12x − 8 = 14 − 6x, अतः x³ − 6x² + 18x = 22।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-146","question":"What is the minimum value of sin²θ + cos⁴θ?","options":["1/2","1","3/4","0"],"answer":2,"explanation":"With s = sin²θ, the expression is s + (1 − s)² = s² − s + 1 = (s − 1/2)² + 3/4, least at s = 1/2. Minimum = 3/4.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"sin²θ + cos⁴θ का न्यूनतम मान क्या है?","optionsHi":["1/2","1","3/4","0"],"explanationHi":"s = sin²θ लेने पर व्यंजक s + (1 − s)² = s² − s + 1 = (s − 1/2)² + 3/4 है, जो s = 1/2 पर न्यूनतम होता है। न्यूनतम मान = 3/4।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-147","question":"In triangle ABC, ∠A = 90°, AB = 8 cm and AC = 6 cm. The bisector of ∠A meets BC at D. What is BD?","options":["30/7 cm","5 cm","32/7 cm","40/7 cm"],"answer":3,"explanation":"BC = 10 cm, and the bisector divides it in the ratio AB : AC = 4 : 3. BD = 10 × 4/7 = 40/7 cm; 30/7 cm is DC.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"त्रिभुज ABC में ∠A = 90°, AB = 8 cm और AC = 6 cm है। ∠A का समद्विभाजक BC को D पर मिलता है। BD कितना है?","optionsHi":["30/7 cm","5 cm","32/7 cm","40/7 cm"],"explanationHi":"BC = 10 cm, और समद्विभाजक इसे AB : AC = 4 : 3 के अनुपात में बाँटता है। BD = 10 × 4/7 = 40/7 cm; 30/7 cm तो DC है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-148","question":"P is a point inside an equilateral triangle of side 12 cm. What is the sum of the perpendicular distances from P to the three sides?","options":["6√3 cm","12 cm","4√3 cm","18 cm"],"answer":0,"explanation":"Splitting the triangle at P: ½ × 12 × (p + q + r) = (√3/4) × 144, so p + q + r = 6√3 cm, the altitude, wherever P is (Viviani's theorem).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"P, 12 cm भुजा वाले समबाहु त्रिभुज के अंदर स्थित एक बिंदु है। P से तीनों भुजाओं पर डाले गए लंबों की लंबाइयों का योग कितना है?","optionsHi":["6√3 cm","12 cm","4√3 cm","18 cm"],"explanationHi":"P पर त्रिभुज को तीन भागों में बाँटने पर: ½ × 12 × (p + q + r) = (√3/4) × 144, अतः p + q + r = 6√3 cm, जो शीर्षलंब के बराबर है, P कहीं भी हो (विवियानी का प्रमेय)।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-149","question":"The vertices of a triangle are (2, 3), (−4, 7) and (8, −4). How far is its centroid from the origin?","options":["2 units","2√2 units","4 units","√5 units"],"answer":1,"explanation":"Centroid = ((2 − 4 + 8)/3, (3 + 7 − 4)/3) = (2, 2). Distance from the origin = √8 = 2√2 units.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक त्रिभुज के शीर्ष (2, 3), (−4, 7) और (8, −4) हैं। उसका केंद्रक मूल बिंदु से कितनी दूर है?","optionsHi":["2 इकाई","2√2 इकाई","4 इकाई","√5 इकाई"],"explanationHi":"केंद्रक = ((2 − 4 + 8)/3, (3 + 7 − 4)/3) = (2, 2)। मूल बिंदु से दूरी = √8 = 2√2 इकाई।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-150","question":"If α and β are the roots of x² − 5x + 3 = 0, what is the value of α/β + β/α?","options":["25/3","31/3","19/3","5/3"],"answer":2,"explanation":"α/β + β/α = (α² + β²)/αβ = ((α + β)² − 2αβ)/αβ = (25 − 6)/3 = 19/3. 25/3 forgets the −2αβ.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि α और β समीकरण x² − 5x + 3 = 0 के मूल हैं, तो α/β + β/α का मान क्या है?","optionsHi":["25/3","31/3","19/3","5/3"],"explanationHi":"α/β + β/α = (α² + β²)/αβ = ((α + β)² − 2αβ)/αβ = (25 − 6)/3 = 19/3। 25/3 में −2αβ छूट गया है।","subtopic":"equations-roots"},
  {"id":"quant-algebra-geometry-151","question":"If 3ˣ = 5ʸ = 75ᶻ, which of the following is true?","options":["z = xy/(x + 2y)","z = 2xy/(x + y)","z = (x + 2y)/xy","z = xy/(2x + y)"],"answer":3,"explanation":"Let each equal k: 3 = k^(1/x), 5 = k^(1/y), 75 = k^(1/z). Since 75 = 3 × 5², 1/z = 1/x + 2/y = (y + 2x)/xy, so z = xy/(2x + y).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि 3ˣ = 5ʸ = 75ᶻ है, तो निम्नलिखित में से कौन सा सत्य है?","optionsHi":["z = xy/(x + 2y)","z = 2xy/(x + y)","z = (x + 2y)/xy","z = xy/(2x + y)"],"explanationHi":"प्रत्येक को k के बराबर मानें: 3 = k^(1/x), 5 = k^(1/y), 75 = k^(1/z)। चूँकि 75 = 3 × 5², 1/z = 1/x + 2/y = (y + 2x)/xy, अतः z = xy/(2x + y)।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-152","question":"What is the value of sin²5° + sin²10° + sin²15° + … + sin²90°?","options":["19/2","9","10","17/2"],"answer":0,"explanation":"Pair sin²θ with sin²(90° − θ) = cos²θ: (5°, 85°) … (40°, 50°) give 8 pairs of 1. Add sin²45° = 1/2 and sin²90° = 1: total 9.5 = 19/2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"sin²5° + sin²10° + sin²15° + … + sin²90° का मान क्या है?","optionsHi":["19/2","9","10","17/2"],"explanationHi":"sin²θ को sin²(90° − θ) = cos²θ के साथ जोड़ी बनाएँ: (5°, 85°) … (40°, 50°) से 8 जोड़ियाँ बनती हैं, प्रत्येक का योग 1 है। इसमें sin²45° = 1/2 और sin²90° = 1 जोड़ें: कुल 9.5 = 19/2।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-153","question":"In triangle ABC, AB = AC = 10 cm and BC = 12 cm. What is the radius of its circumcircle?","options":["6 cm","6.25 cm","8 cm","5 cm"],"answer":1,"explanation":"The altitude to BC is √(100 − 36) = 8, so the area is 48 cm². R = abc/(4 × area) = 1,200/192 = 6.25 cm.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"त्रिभुज ABC में AB = AC = 10 cm और BC = 12 cm है। इसके परिवृत्त की त्रिज्या क्या है?","optionsHi":["6 cm","6.25 cm","8 cm","5 cm"],"explanationHi":"BC पर शीर्षलंब √(100 − 36) = 8 है, अतः क्षेत्रफल 48 cm² है। R = abc/(4 × क्षेत्रफल) = 1,200/192 = 6.25 cm।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-154","question":"If (x + 1/x)² = 3, what is the value of x²⁰⁶ + x²⁰⁰ + x⁹⁰ + x⁸⁴ + x¹⁸ + x¹² + x⁶ + 1?","options":["1","2","0","8"],"answer":2,"explanation":"x + 1/x = √3, so x³ + 1/x³ = (√3)³ − 3√3 = 0, i.e. x⁶ = −1. Then x²⁰⁶ = x², x²⁰⁰ = −x², x⁹⁰ = −1, x⁸⁴ = 1, x¹⁸ = −1, x¹² = 1, x⁶ = −1, and everything cancels to 0.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि (x + 1/x)² = 3 है, तो x²⁰⁶ + x²⁰⁰ + x⁹⁰ + x⁸⁴ + x¹⁸ + x¹² + x⁶ + 1 का मान क्या है?","optionsHi":["1","2","0","8"],"explanationHi":"x + 1/x = √3, अतः x³ + 1/x³ = (√3)³ − 3√3 = 0, अर्थात x⁶ = −1। तब x²⁰⁶ = x², x²⁰⁰ = −x², x⁹⁰ = −1, x⁸⁴ = 1, x¹⁸ = −1, x¹² = 1, x⁶ = −1, और सब कुछ कटकर 0 रह जाता है।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-155","question":"What is the value of (cos 9° + sin 9°)/(cos 9° − sin 9°)?","options":["tan 36°","tan 9°","1","cot 36°"],"answer":3,"explanation":"Divide by cos 9°: (1 + tan 9°)/(1 − tan 9°) = tan(45° + 9°) = tan 54° = cot 36°.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"(cos 9° + sin 9°)/(cos 9° − sin 9°) का मान क्या है?","optionsHi":["tan 36°","tan 9°","1","cot 36°"],"explanationHi":"cos 9° से भाग देने पर: (1 + tan 9°)/(1 − tan 9°) = tan(45° + 9°) = tan 54° = cot 36°।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-156","question":"What is the value of 2 sin 30° cos 30°?","options":["√3/2","1/2","√3","1"],"answer":0,"explanation":"2 × 1/2 × √3/2 = √3/2, which is also sin 60° (2 sin θ cos θ = sin 2θ).","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"2 sin 30° cos 30° का मान क्या है?","optionsHi":["√3/2","1/2","√3","1"],"explanationHi":"2 × 1/2 × √3/2 = √3/2, जो sin 60° भी है (2 sin θ cos θ = sin 2θ)।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-157","question":"If x − y = 4 and xy = 21, what is the value of x³ − y³?","options":["64","316","148","400"],"answer":1,"explanation":"x³ − y³ = (x − y)³ + 3xy(x − y) = 64 + 252 = 316. (x = 7, y = 3 checks: 343 − 27 = 316.)","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"यदि x − y = 4 और xy = 21 है, तो x³ − y³ का मान क्या है?","optionsHi":["64","316","148","400"],"explanationHi":"x³ − y³ = (x − y)³ + 3xy(x − y) = 64 + 252 = 316। (x = 7, y = 3 से जाँच: 343 − 27 = 316।)","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-158","question":"What is the sum of an interior angle of a regular pentagon and an exterior angle of a regular hexagon?","options":["180°","132°","168°","156°"],"answer":2,"explanation":"Pentagon interior = 180° − 72° = 108°; hexagon exterior = 60°. Sum = 168°.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक सम पंचभुज के आंतरिक कोण और एक सम षट्भुज के बाह्य कोण का योग क्या है?","optionsHi":["180°","132°","168°","156°"],"explanationHi":"पंचभुज का आंतरिक कोण = 180° − 72° = 108°; षट्भुज का बाह्य कोण = 60°। योग = 168°।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-159","question":"The point (2, k) lies on the line 3x − 2y = 4. What is the value of k?","options":["−1","2","5","1"],"answer":3,"explanation":"Substitute x = 2: 6 − 2k = 4, so 2k = 2 and k = 1. −1 comes from a sign slip when moving 6 across, and 5 from adding 6 to 4 instead of subtracting.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"बिंदु (2, k) रेखा 3x − 2y = 4 पर स्थित है। k का मान क्या है?","optionsHi":["−1","2","5","1"],"explanationHi":"x = 2 रखने पर: 6 − 2k = 4, अतः 2k = 2 और k = 1। −1 तब आता है जब 6 को पक्षांतर करते समय चिह्न की गलती हो, और 5 तब जब 4 में से घटाने के बजाय 6 जोड़ दिया जाए।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-160","question":"If a² + b² = 34 and ab = 15, where a and b are positive, what is the value of a + b?","options":["8","2","√34","7"],"answer":0,"explanation":"(a + b)² = a² + b² + 2ab = 34 + 30 = 64, so a + b = 8. 2 is a − b (√(34 − 30)).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि a² + b² = 34 और ab = 15 है, जहाँ a और b धनात्मक हैं, तो a + b का मान क्या है?","optionsHi":["8","2","√34","7"],"explanationHi":"(a + b)² = a² + b² + 2ab = 34 + 30 = 64, अतः a + b = 8। 2 तो a − b है (√(34 − 30))।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-161","question":"In a cyclic quadrilateral ABCD, ∠A = 3∠C. What is ∠A?","options":["45°","135°","120°","108°"],"answer":1,"explanation":"Opposite angles of a cyclic quadrilateral are supplementary: 3∠C + ∠C = 180°, so ∠C = 45° and ∠A = 135°.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"चक्रीय चतुर्भुज ABCD में ∠A = 3∠C है। ∠A कितना है?","optionsHi":["45°","135°","120°","108°"],"explanationHi":"चक्रीय चतुर्भुज के सम्मुख कोण संपूरक होते हैं: 3∠C + ∠C = 180°, अतः ∠C = 45° और ∠A = 135°।","subtopic":"circles"},
  {"id":"quant-algebra-geometry-162","question":"If tan A = 1/2 and tan B = 1/3, where A and B are acute, what is A + B?","options":["60°","30°","45°","90°"],"answer":2,"explanation":"tan(A + B) = (1/2 + 1/3)/(1 − 1/6) = (5/6)/(5/6) = 1, so A + B = 45°.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि tan A = 1/2 और tan B = 1/3 है, जहाँ A और B न्यूनकोण हैं, तो A + B कितना है?","optionsHi":["60°","30°","45°","90°"],"explanationHi":"tan(A + B) = (1/2 + 1/3)/(1 − 1/6) = (5/6)/(5/6) = 1, अतः A + B = 45°।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-163","question":"G is the centroid of triangle ABC, whose area is 72 cm². What is the area of triangle BGC?","options":["36 cm²","18 cm²","12 cm²","24 cm²"],"answer":3,"explanation":"The centroid divides the triangle into three triangles of equal area (GBC, GCA, GAB), so each is 72/3 = 24 cm². 12 cm² is the area of each of the six small triangles made by the medians.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"G त्रिभुज ABC का केंद्रक है, जिसका क्षेत्रफल 72 cm² है। त्रिभुज BGC का क्षेत्रफल कितना है?","optionsHi":["36 cm²","18 cm²","12 cm²","24 cm²"],"explanationHi":"केंद्रक त्रिभुज को समान क्षेत्रफल वाले तीन त्रिभुजों (GBC, GCA, GAB) में बाँटता है, अतः प्रत्येक का क्षेत्रफल 72/3 = 24 cm² है। 12 cm² माध्यिकाओं से बने छह छोटे त्रिभुजों में से प्रत्येक का क्षेत्रफल है।","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-164","question":"If 4ˣ − 4ˣ⁻¹ = 24, what is the value of (2x)ˣ?","options":["25√5","125","5√5","25"],"answer":0,"explanation":"4ˣ⁻¹(4 − 1) = 24 gives 4ˣ⁻¹ = 8, i.e. 2²ˣ⁻² = 2³, so x = 5/2. Then (2x)ˣ = 5^(5/2) = 25√5.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"यदि 4ˣ − 4ˣ⁻¹ = 24 है, तो (2x)ˣ का मान क्या है?","optionsHi":["25√5","125","5√5","25"],"explanationHi":"4ˣ⁻¹(4 − 1) = 24 से 4ˣ⁻¹ = 8, अर्थात 2²ˣ⁻² = 2³, अतः x = 5/2। तब (2x)ˣ = 5^(5/2) = 25√5।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-165","question":"If a + b + c = 0 (not all zero), what is the value of (a² + b² + c²)²/(a⁴ + b⁴ + c⁴)?","options":["1","2","4","1/2"],"answer":1,"explanation":"With a + b + c = 0, a² + b² + c² = −2(ab + bc + ca) and a⁴ + b⁴ + c⁴ = (a² + b² + c²)²/2. So the ratio is 2. Check with 1, 1, −2: 36/18 = 2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि a + b + c = 0 है (सभी शून्य नहीं), तो (a² + b² + c²)²/(a⁴ + b⁴ + c⁴) का मान क्या है?","optionsHi":["1","2","4","1/2"],"explanationHi":"a + b + c = 0 होने पर a² + b² + c² = −2(ab + bc + ca) और a⁴ + b⁴ + c⁴ = (a² + b² + c²)²/2। अतः अनुपात 2 है। 1, 1, −2 से जाँच: 36/18 = 2।","subtopic":"algebraic-identities"},
  {"id":"quant-algebra-geometry-166","question":"What is the value of sin 10° × sin 50° × sin 70°?","options":["1/4","√3/8","1/8","1/16"],"answer":2,"explanation":"sin θ sin(60° − θ) sin(60° + θ) = ¼ sin 3θ. With θ = 10°: ¼ × sin 30° = 1/8.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"sin 10° × sin 50° × sin 70° का मान क्या है?","optionsHi":["1/4","√3/8","1/8","1/16"],"explanationHi":"sin θ sin(60° − θ) sin(60° + θ) = ¼ sin 3θ। θ = 10° लेने पर: ¼ × sin 30° = 1/8।","subtopic":"trigonometry"},
  {"id":"quant-algebra-geometry-167","question":"A right triangle has sides 5 cm, 12 cm and 13 cm. What is the distance between its incentre and its circumcentre?","options":["√13 cm","5/2 cm","√17 cm","√65/2 cm"],"answer":3,"explanation":"R = 13/2 and r = (5 + 12 − 13)/2 = 2. Euler: d² = R² − 2Rr = 169/4 − 26 = 65/4, so d = √65/2 cm. (Coordinates confirm: I = (2, 2), O = (2.5, 6).)","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक समकोण त्रिभुज की भुजाएँ 5 cm, 12 cm और 13 cm हैं। उसके अंतःकेंद्र और परिकेंद्र के बीच की दूरी कितनी है?","optionsHi":["√13 cm","5/2 cm","√17 cm","√65/2 cm"],"explanationHi":"R = 13/2 और r = (5 + 12 − 13)/2 = 2। यूलर सूत्र: d² = R² − 2Rr = 169/4 − 26 = 65/4, अतः d = √65/2 cm। (निर्देशांकों से पुष्टि: I = (2, 2), O = (2.5, 6)।)","subtopic":"triangles-lines"},
  {"id":"quant-algebra-geometry-168","question":"What are the coordinates of the point that divides the join of A(−3, 5) and B(7, −5) externally in the ratio 3 : 2?","options":["(27, −25)","(3, −1)","(−23, 25)","(15, −13)"],"answer":0,"explanation":"External division: ((3 × 7 − 2 × (−3))/(3 − 2), (3 × (−5) − 2 × 5)/(3 − 2)) = (27, −25). (3, −1) is the internal division point.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A(−3, 5) और B(7, −5) को मिलाने वाले रेखाखंड को 3 : 2 के अनुपात में बाह्य विभाजित करने वाले बिंदु के निर्देशांक क्या हैं?","optionsHi":["(27, −25)","(3, −1)","(−23, 25)","(15, −13)"],"explanationHi":"बाह्य विभाजन: ((3 × 7 − 2 × (−3))/(3 − 2), (3 × (−5) − 2 × 5)/(3 − 2)) = (27, −25)। (3, −1) अंतः विभाजन बिंदु है।","subtopic":"coordinate-geometry"},
  {"id":"quant-algebra-geometry-169","question":"If x = (√5 + 1)/(√5 − 1) and y = (√5 − 1)/(√5 + 1), what is the value of x² + y²?","options":["9","7","5","3"],"answer":1,"explanation":"xy = 1 and x + y = [(√5 + 1)² + (√5 − 1)²]/4 = 12/4 = 3. So x² + y² = 9 − 2 = 7.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि x = (√5 + 1)/(√5 − 1) और y = (√5 − 1)/(√5 + 1) है, तो x² + y² का मान क्या है?","optionsHi":["9","7","5","3"],"explanationHi":"xy = 1 और x + y = [(√5 + 1)² + (√5 − 1)²]/4 = 12/4 = 3। अतः x² + y² = 9 − 2 = 7।","subtopic":"surds-indices"},
  {"id":"quant-algebra-geometry-170","question":"A man 1.5 m tall sees the top of a tower at an angle of elevation of 30°. After walking 30 m towards the tower, he sees it at 60°. What is the height of the tower?","options":["15√3 m","(30√3 + 1.5) m","(15√3 + 1.5) m","(10√3 + 1.5) m"],"answer":2,"explanation":"Above eye level, h′(cot 30° − cot 60°) = 30, i.e. h′ × 2/√3 = 30, so h′ = 15√3 m. Add the man's height: (15√3 + 1.5) m. 15√3 m forgets the eye level.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1.5 m लंबा एक व्यक्ति किसी मीनार के शीर्ष को 30° के उन्नयन कोण पर देखता है। मीनार की ओर 30 m चलने के बाद वह उसे 60° पर देखता है। मीनार की ऊँचाई कितनी है?","optionsHi":["15√3 m","(30√3 + 1.5) m","(15√3 + 1.5) m","(10√3 + 1.5) m"],"explanationHi":"आँख के स्तर से ऊपर, h′(cot 30° − cot 60°) = 30, अर्थात h′ × 2/√3 = 30, अतः h′ = 15√3 m। व्यक्ति की ऊँचाई जोड़ें: (15√3 + 1.5) m। 15√3 m में आँख का स्तर छूट गया है।","subtopic":"heights-distances"},
  {"id":"quant-algebra-geometry-171","question":"If α and β are the roots of 2x² − 6x + 1 = 0, what is the value of α/β + β/α?","options":["16","8","18","14"],"answer":0,"explanation":"α + β = 3 and αβ = 1/2, so α² + β² = 9 − 1 = 8. Then α/β + β/α = (α² + β²)/(αβ) = 8 ÷ 1/2 = 16.","difficulty":"hard","questionHi":"यदि α और β समीकरण 2x² − 6x + 1 = 0 के मूल हैं, तो α/β + β/α का मान क्या है?","optionsHi":["16","8","18","14"],"explanationHi":"α + β = 3 और αβ = 1/2, अतः α² + β² = 9 − 1 = 8। तब α/β + β/α = (α² + β²)/(αβ) = 8 ÷ 1/2 = 16।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-172","question":"The roots of x² + bx + 48 = 0 are real and differ by 2. If b is positive, what is b?","options":["12","16","10","14"],"answer":3,"explanation":"Roots r and r + 2 with r(r + 2) = 48 give r = 6 or r = −8, i.e. the pairs (6, 8) or (−8, −6). The sum of roots equals −b, so b = 14 needs the negative pair (−8, −6); the pair (6, 8) gives b = −14.","difficulty":"hard","questionHi":"समीकरण x² + bx + 48 = 0 के मूल वास्तविक हैं और उनका अंतर 2 है। यदि b धनात्मक है, तो b का मान क्या है?","optionsHi":["12","16","10","14"],"explanationHi":"मूल r और r + 2 हों तो r(r + 2) = 48 से r = 6 या r = −8, यानी जोड़ी (6, 8) या (−8, −6)। मूलों का योग −b के बराबर है, इसलिए b = 14 के लिए ऋणात्मक जोड़ी (−8, −6) चाहिए; जोड़ी (6, 8) से b = −14 आता है।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-173","question":"How many ordered pairs (x, y) of real numbers satisfy both x² + y² = 65 and xy = 28?","options":["2","4","8","6"],"answer":1,"explanation":"(x + y)² = 65 + 56 = 121 and (x − y)² = 65 − 56 = 9, so x + y = ±11 and x − y = ±3. The four sign choices give (7, 4), (4, 7), (−4, −7), (−7, −4), so there are 4 pairs.","difficulty":"hard","questionHi":"वास्तविक संख्याओं के कितने क्रमित युग्म (x, y) दोनों समीकरणों x² + y² = 65 और xy = 28 को संतुष्ट करते हैं?","optionsHi":["2","4","8","6"],"explanationHi":"(x + y)² = 65 + 56 = 121 और (x − y)² = 65 − 56 = 9, अतः x + y = ±11 और x − y = ±3। चार चिह्न-संयोजनों से (7, 4), (4, 7), (−4, −7), (−7, −4) मिलते हैं, इसलिए 4 युग्म हैं।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-174","question":"What is the sum of all real solutions of √(2x + 9) − √(x − 4) = 3?","options":["20","28","8","36"],"answer":1,"explanation":"Write √(2x + 9) = 3 + √(x − 4) and square: x + 4 = 6√(x − 4). Squaring again gives x² − 28x + 160 = 0, so x = 8 or 20. Both satisfy the original equation (5 − 2 = 3 and 7 − 4 = 3), so the sum is 28.","difficulty":"very-hard","questionHi":"समीकरण √(2x + 9) − √(x − 4) = 3 के सभी वास्तविक हलों का योग क्या है?","optionsHi":["20","28","8","36"],"explanationHi":"√(2x + 9) = 3 + √(x − 4) लिखकर वर्ग करने पर x + 4 = 6√(x − 4)। फिर वर्ग करने पर x² − 28x + 160 = 0, अतः x = 8 या 20। दोनों मूल मूल समीकरण को संतुष्ट करते हैं (5 − 2 = 3 और 7 − 4 = 3), इसलिए योग 28 है।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-175","question":"If α and β are the roots of x² − 6x + 4 = 0, which quadratic equation has roots α² and β²?","options":["x² − 36x + 16 = 0","x² − 28x + 4 = 0","x² − 20x + 16 = 0","x² − 28x + 16 = 0"],"answer":3,"explanation":"α + β = 6 and αβ = 4. Sum of new roots = α² + β² = 36 − 8 = 28, product = (αβ)² = 16, so the equation is x² − 28x + 16 = 0.","difficulty":"hard","questionHi":"यदि α और β समीकरण x² − 6x + 4 = 0 के मूल हैं, तो किस द्विघात समीकरण के मूल α² और β² हैं?","optionsHi":["x² − 36x + 16 = 0","x² − 28x + 4 = 0","x² − 20x + 16 = 0","x² − 28x + 16 = 0"],"explanationHi":"α + β = 6 और αβ = 4। नए मूलों का योग = α² + β² = 36 − 8 = 28, गुणनफल = (αβ)² = 16, अतः समीकरण x² − 28x + 16 = 0 है।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-176","question":"For which values of k does (k + 1)x² − 2(k − 1)x + 1 = 0 have equal roots?","options":["0 or 3","3 only","0 or −3","1 or 3"],"answer":0,"explanation":"Equal roots need discriminant 0: 4(k − 1)² − 4(k + 1) = 0 gives k² − 3k = 0, so k = 0 or 3. k = 0 is allowed because the equation is still quadratic (x² + 2x + 1 = 0).","difficulty":"very-hard","questionHi":"k के किन मानों के लिए समीकरण (k + 1)x² − 2(k − 1)x + 1 = 0 के मूल बराबर होंगे?","optionsHi":["0 या 3","केवल 3","0 या −3","1 या 3"],"explanationHi":"बराबर मूलों के लिए विविक्तकर 0 होना चाहिए: 4(k − 1)² − 4(k + 1) = 0 से k² − 3k = 0, अतः k = 0 या 3। k = 0 मान्य है क्योंकि समीकरण तब भी द्विघात है (x² + 2x + 1 = 0)।","subtopic":"equations-roots","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-177","question":"If 2^x = 3^y = 6^z, x = 6 and y = 3, what is the value of z?","options":["3","4","1.5","2"],"answer":3,"explanation":"Let each equal k. Then 2 = k^(1/x), 3 = k^(1/y), 6 = k^(1/z), and 2 × 3 = 6 gives 1/x + 1/y = 1/z. So 1/z = 1/6 + 1/3 = 1/2 and z = 2.","difficulty":"hard","questionHi":"यदि 2^x = 3^y = 6^z, x = 6 और y = 3 है, तो z का मान क्या है?","optionsHi":["3","4","1.5","2"],"explanationHi":"तीनों को k के बराबर मानें। तब 2 = k^(1/x), 3 = k^(1/y), 6 = k^(1/z), और 2 × 3 = 6 से 1/x + 1/y = 1/z। अतः 1/z = 1/6 + 1/3 = 1/2 और z = 2।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-178","question":"What is the value of (3^(n+4) − 6 × 3^(n+1)) ÷ 3^(n+2)?","options":["9","7","21","63"],"answer":1,"explanation":"Take 3^n common: (81 − 18) × 3^n ÷ (9 × 3^n) = 63/9 = 7. The value 63 forgets to divide by 3² = 9.","difficulty":"moderate","questionHi":"(3^(n+4) − 6 × 3^(n+1)) ÷ 3^(n+2) का मान क्या है?","optionsHi":["9","7","21","63"],"explanationHi":"3^n उभयनिष्ठ लेने पर: (81 − 18) × 3^n ÷ (9 × 3^n) = 63/9 = 7। मान 63 में 3² = 9 से भाग देना छूट गया है।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-179","question":"For a positive real x ≠ 1, if x^(x√x) = (x√x)^x, what is x?","options":["3/2","9/4","4/9","9/2"],"answer":1,"explanation":"(x√x)^x = (x^(3/2))^x = x^(3x/2). Equal bases (x ≠ 1) need equal powers: x√x = 3x/2, so √x = 3/2 and x = 9/4.","difficulty":"very-hard","questionHi":"x ≠ 1 वाले धनात्मक वास्तविक x के लिए, यदि x^(x√x) = (x√x)^x है, तो x का मान क्या है?","optionsHi":["3/2","9/4","4/9","9/2"],"explanationHi":"(x√x)^x = (x^(3/2))^x = x^(3x/2)। आधार बराबर (x ≠ 1) होने पर घात बराबर होनी चाहिए: x√x = 3x/2, अतः √x = 3/2 और x = 9/4।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-180","question":"The angle of elevation of the top of a tower from a point on level ground is 30°. After walking 50 m towards the tower, the angle becomes 60°. What is the height of the tower?","options":["50√3 m","25 m","50/√3 m","25√3 m"],"answer":3,"explanation":"h cot 30° − h cot 60° = 50 gives h(√3 − 1/√3) = h × 2/√3 = 50, so h = 25√3 m.","difficulty":"hard","questionHi":"समतल भूमि पर स्थित एक बिंदु से किसी मीनार के शिखर का उन्नयन कोण 30° है। मीनार की ओर 50 m चलने पर कोण 60° हो जाता है। मीनार की ऊँचाई कितनी है?","optionsHi":["50√3 m","25 m","50/√3 m","25√3 m"],"explanationHi":"h cot 30° − h cot 60° = 50 से h(√3 − 1/√3) = h × 2/√3 = 50, अतः h = 25√3 m।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-181","question":"From the top of a 60 m high building, the angles of depression of the top and the bottom of a tower are 30° and 60° respectively. What is the height of the tower?","options":["40 m","20 m","30 m","45 m"],"answer":0,"explanation":"Horizontal distance = 60 cot 60° = 20√3 m. The drop to the top of the tower is 20√3 × tan 30° = 20 m, so the tower is 60 − 20 = 40 m high; 20 m is only the drop.","difficulty":"very-hard","questionHi":"60 m ऊँची एक इमारत के शिखर से किसी मीनार के शिखर और आधार के अवनमन कोण क्रमशः 30° और 60° हैं। मीनार की ऊँचाई कितनी है?","optionsHi":["40 m","20 m","30 m","45 m"],"explanationHi":"क्षैतिज दूरी = 60 cot 60° = 20√3 m। मीनार के शिखर तक की गिरावट 20√3 × tan 30° = 20 m है, अतः मीनार की ऊँचाई 60 − 20 = 40 m; 20 m केवल गिरावट है।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-182","question":"Two points lie on the same side of a pole, in line with its foot, at distances of 9 m and 16 m from the foot. The angles of elevation of the top of the pole from these points are complementary. What is the height of the pole?","options":["12.5 m","10 m","12 m","25 m"],"answer":2,"explanation":"If the angles are θ and 90° − θ, tan θ = h/9 and tan(90° − θ) = h/16, and their product is 1: h²/(9 × 16) = 1, so h = √144 = 12 m. The mean 12.5 is the trap.","difficulty":"hard","questionHi":"एक खंभे के आधार की सीध में, खंभे के एक ही ओर दो बिंदु आधार से 9 m और 16 m की दूरी पर हैं। इन बिंदुओं से खंभे के शिखर के उन्नयन कोण पूरक हैं। खंभे की ऊँचाई कितनी है?","optionsHi":["12.5 m","10 m","12 m","25 m"],"explanationHi":"यदि कोण θ और 90° − θ हों, तो tan θ = h/9 और tan(90° − θ) = h/16, तथा इनका गुणनफल 1 है: h²/(9 × 16) = 1, अतः h = √144 = 12 m। माध्य 12.5 गलत जाल है।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-183","question":"From the top of a 100 m high cliff, the angles of depression of two boats on opposite sides of the cliff are 45° and 30°. What is the distance between the boats?","options":["100(√3 − 1) m","100√3 m","100(√3 + 1) m","200 m"],"answer":2,"explanation":"The boats are 100 cot 45° = 100 m and 100 cot 30° = 100√3 m from the foot, on opposite sides, so the distance is 100 + 100√3 = 100(√3 + 1) m. For the same side it would be 100(√3 − 1).","difficulty":"very-hard","questionHi":"100 m ऊँची एक चट्टान के शिखर से चट्टान के विपरीत किनारों पर स्थित दो नावों के अवनमन कोण 45° और 30° हैं। दोनों नावों के बीच की दूरी कितनी है?","optionsHi":["100(√3 − 1) m","100√3 m","100(√3 + 1) m","200 m"],"explanationHi":"नावें आधार से 100 cot 45° = 100 m और 100 cot 30° = 100√3 m की दूरी पर विपरीत ओर हैं, इसलिए दूरी 100 + 100√3 = 100(√3 + 1) m। एक ही ओर होने पर यह 100(√3 − 1) होती।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-184","question":"A flagstaff stands on top of a tower. From a point 30 m from the foot of the tower, the angles of elevation of the top of the tower and the top of the flagstaff are 45° and 60°. What is the length of the flagstaff?","options":["30(√3 − 1) m","30√3 m","30(√3 + 1) m","15√3 m"],"answer":0,"explanation":"Tower = 30 tan 45° = 30 m. Tower plus flagstaff = 30 tan 60° = 30√3 m. The flagstaff is 30√3 − 30 = 30(√3 − 1) m.","difficulty":"hard","questionHi":"एक मीनार के शिखर पर एक झंडे का डंडा लगा है। मीनार के आधार से 30 m की दूरी पर स्थित एक बिंदु से मीनार के शिखर और डंडे के शिखर के उन्नयन कोण 45° और 60° हैं। डंडे की लंबाई कितनी है?","optionsHi":["30(√3 − 1) m","30√3 m","30(√3 + 1) m","15√3 m"],"explanationHi":"मीनार = 30 tan 45° = 30 m। मीनार और डंडे की कुल ऊँचाई = 30 tan 60° = 30√3 m। डंडे की लंबाई 30√3 − 30 = 30(√3 − 1) m है।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-185","question":"When the altitude of the sun changes from 45° to 30°, the shadow of a vertical tower lengthens by 40 m. What is the height of the tower?","options":["40(√3 + 1) m","20(√3 − 1) m","40√3 m","20(√3 + 1) m"],"answer":3,"explanation":"Shadow lengths are h cot 45° = h and h cot 30° = h√3, so h(√3 − 1) = 40. Then h = 40/(√3 − 1) = 40(√3 + 1)/2 = 20(√3 + 1) m.","difficulty":"very-hard","questionHi":"जब सूर्य का उन्नयन कोण 45° से घटकर 30° हो जाता है, तो एक ऊर्ध्वाधर मीनार की छाया 40 m बढ़ जाती है। मीनार की ऊँचाई कितनी है?","optionsHi":["40(√3 + 1) m","20(√3 − 1) m","40√3 m","20(√3 + 1) m"],"explanationHi":"छाया की लंबाइयाँ h cot 45° = h और h cot 30° = h√3 हैं, अतः h(√3 − 1) = 40। तब h = 40/(√3 − 1) = 40(√3 + 1)/2 = 20(√3 + 1) m।","subtopic":"heights-distances","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-186","question":"In what ratio does the x-axis divide the line segment joining (3, −4) and (−5, 6)?","options":["3 : 2","2 : 3","1 : 2","4 : 5"],"answer":1,"explanation":"Let the ratio be m : n. The y-coordinate is zero: (6m − 4n)/(m + n) = 0, so 6m = 4n and m : n = 2 : 3. The opposite signs of y confirm the division is internal.","difficulty":"moderate","questionHi":"x-अक्ष बिंदुओं (3, −4) और (−5, 6) को मिलाने वाले रेखाखंड को किस अनुपात में विभाजित करता है?","optionsHi":["3 : 2","2 : 3","1 : 2","4 : 5"],"explanationHi":"अनुपात m : n मानें। y-निर्देशांक शून्य है: (6m − 4n)/(m + n) = 0, अतः 6m = 4n और m : n = 2 : 3। y के विपरीत चिह्न बताते हैं कि विभाजन आंतरिक है।","subtopic":"coordinate-geometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-187","question":"A point P(x, y) is equidistant from A(2, 3) and B(6, −1). Which equation does P satisfy?","options":["x + y = 5","x − y = 3","x − y = 1","x + y = 3"],"answer":1,"explanation":"PA² = PB² gives (x − 2)² + (y − 3)² = (x − 6)² + (y + 1)², which simplifies to 8x − 8y = 24, i.e. x − y = 3. (It is the perpendicular bisector of AB through the midpoint (4, 1).)","difficulty":"hard","questionHi":"एक बिंदु P(x, y), A(2, 3) और B(6, −1) से समान दूरी पर है। P किस समीकरण को संतुष्ट करता है?","optionsHi":["x + y = 5","x − y = 3","x − y = 1","x + y = 3"],"explanationHi":"PA² = PB² से (x − 2)² + (y − 3)² = (x − 6)² + (y + 1)², जो सरल होकर 8x − 8y = 24, यानी x − y = 3 देता है। (यह AB का लंब समद्विभाजक है जो मध्य-बिंदु (4, 1) से गुजरता है।)","subtopic":"coordinate-geometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-188","question":"Two vertices of a triangle are (1, 2) and (7, −2), and its centroid is (4, 3). What is the third vertex?","options":["(4, 5)","(6, 7)","(5, 9)","(4, 9)"],"answer":3,"explanation":"The centroid is the average of the vertices: x = 3 × 4 − 1 − 7 = 4 and y = 3 × 3 − 2 + 2 = 9, so the third vertex is (4, 9).","difficulty":"hard","questionHi":"एक त्रिभुज के दो शीर्ष (1, 2) और (7, −2) हैं और उसका केंद्रक (4, 3) है। तीसरा शीर्ष क्या है?","optionsHi":["(4, 5)","(6, 7)","(5, 9)","(4, 9)"],"explanationHi":"केंद्रक शीर्षों का औसत होता है: x = 3 × 4 − 1 − 7 = 4 और y = 3 × 3 − 2 + 2 = 9, अतः तीसरा शीर्ष (4, 9) है।","subtopic":"coordinate-geometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-189","question":"The line 3x + 4y = 60 together with the coordinate axes forms a triangle. What is the radius of the circle inscribed in this triangle?","options":["5","6","7.5","10"],"answer":0,"explanation":"The intercepts are 20 on the x-axis and 15 on the y-axis, so the right triangle has legs 20 and 15 and hypotenuse 25. For a right triangle, r = (20 + 15 − 25)/2 = 5. (Check: area 150 ÷ semi-perimeter 30 = 5.)","difficulty":"hard","questionHi":"रेखा 3x + 4y = 60 निर्देशांक अक्षों के साथ एक त्रिभुज बनाती है। इस त्रिभुज के अंतःवृत्त की त्रिज्या कितनी है?","optionsHi":["5","6","7.5","10"],"explanationHi":"अंतःखंड x-अक्ष पर 20 और y-अक्ष पर 15 हैं, अतः समकोण त्रिभुज की भुजाएँ 20 और 15 तथा कर्ण 25 है। समकोण त्रिभुज के लिए r = (20 + 15 − 25)/2 = 5। (जाँच: क्षेत्रफल 150 ÷ अर्धपरिमाप 30 = 5।)","subtopic":"coordinate-geometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-190","question":"The line through (2, 3) and (k, 7) is perpendicular to the line through (1, 1) and (3, 5). What is k?","options":["10","6","−6","−10"],"answer":2,"explanation":"The second line has slope (5 − 1)/(3 − 1) = 2, so the first must have slope −1/2: (7 − 3)/(k − 2) = −1/2, giving k − 2 = −8 and k = −6.","difficulty":"hard","questionHi":"बिंदुओं (2, 3) और (k, 7) से गुजरने वाली रेखा, बिंदुओं (1, 1) और (3, 5) से गुजरने वाली रेखा पर लंब है। k का मान क्या है?","optionsHi":["10","6","−6","−10"],"explanationHi":"दूसरी रेखा की ढाल (5 − 1)/(3 − 1) = 2 है, अतः पहली की ढाल −1/2 होनी चाहिए: (7 − 3)/(k − 2) = −1/2, जिससे k − 2 = −8 और k = −6।","subtopic":"coordinate-geometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-191","question":"Two circles of radii 13 cm and 15 cm intersect, and their common chord is 24 cm long. If the centres lie on opposite sides of the common chord, what is the distance between the centres?","options":["4 cm","12 cm","14 cm","16 cm"],"answer":2,"explanation":"Half the chord is 12 cm. The distances from the chord to the centres are √(13² − 12²) = 5 and √(15² − 12²) = 9. On opposite sides these add up: 5 + 9 = 14 cm (on the same side it would be 4 cm).","difficulty":"very-hard","questionHi":"13 cm और 15 cm त्रिज्या वाले दो वृत्त एक-दूसरे को काटते हैं और उनकी उभयनिष्ठ जीवा 24 cm लंबी है। यदि केंद्र उभयनिष्ठ जीवा के विपरीत ओर हैं, तो केंद्रों के बीच की दूरी कितनी है?","optionsHi":["4 cm","12 cm","14 cm","16 cm"],"explanationHi":"जीवा का आधा भाग 12 cm है। जीवा से केंद्रों की दूरियाँ √(13² − 12²) = 5 और √(15² − 12²) = 9 हैं। विपरीत ओर होने पर ये जुड़ती हैं: 5 + 9 = 14 cm (एक ही ओर होने पर 4 cm होती)।","subtopic":"circles","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-192","question":"Two circles with radii 11 cm and 4 cm have their centres 25 cm apart. What is the difference between the lengths of their direct common tangent and their transverse common tangent?","options":["4 cm","3 cm","5 cm","7 cm"],"answer":0,"explanation":"Direct tangent = √(25² − (11 − 4)²) = √576 = 24 cm. Transverse tangent = √(25² − (11 + 4)²) = √400 = 20 cm. The difference is 24 − 20 = 4 cm.","difficulty":"very-hard","questionHi":"11 cm और 4 cm त्रिज्या वाले दो वृत्तों के केंद्रों के बीच की दूरी 25 cm है। उनकी सरल (बाह्य) उभयनिष्ठ स्पर्श रेखा और तिर्यक (अंतः) उभयनिष्ठ स्पर्श रेखा की लंबाइयों का अंतर कितना है?","optionsHi":["4 cm","3 cm","5 cm","7 cm"],"explanationHi":"सरल उभयनिष्ठ स्पर्श रेखा = √(25² − (11 − 4)²) = √576 = 24 cm। तिर्यक उभयनिष्ठ स्पर्श रेखा = √(25² − (11 + 4)²) = √400 = 20 cm। अंतर 24 − 20 = 4 cm है।","subtopic":"circles","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-193","question":"A, B, C, D are the vertices of a cyclic quadrilateral in order, and ∠A : ∠B : ∠C = 2 : 3 : 4. What is ∠D?","options":["60°","120°","100°","90°"],"answer":3,"explanation":"Opposite angles are supplementary: 2k + 4k = 180°, so k = 30° and ∠B = 3k = 90°. Then ∠D = 180° − ∠B = 90°.","difficulty":"moderate","questionHi":"A, B, C, D एक चक्रीय चतुर्भुज के क्रमागत शीर्ष हैं और ∠A : ∠B : ∠C = 2 : 3 : 4 है। ∠D का मान क्या है?","optionsHi":["60°","120°","100°","90°"],"explanationHi":"सम्मुख कोण संपूरक होते हैं: 2k + 4k = 180°, अतः k = 30° और ∠B = 3k = 90°। तब ∠D = 180° − ∠B = 90°।","subtopic":"circles","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-194","question":"From an external point P, a secant meets a circle at A and B with PA = 4 cm and AB = 5 cm, and another secant meets it at C and D with PC = 3 cm. What is CD?","options":["12 cm","9 cm","6 cm","15 cm"],"answer":1,"explanation":"PA × PB = PC × PD with PB = 4 + 5 = 9 gives 36 = 3 × PD, so PD = 12 and CD = PD − PC = 12 − 3 = 9 cm. 12 cm is PD, not CD.","difficulty":"hard","questionHi":"बाह्य बिंदु P से खींची गई एक छेदक रेखा वृत्त को A और B पर काटती है, जहाँ PA = 4 cm और AB = 5 cm है, और दूसरी छेदक रेखा इसे C और D पर काटती है, जहाँ PC = 3 cm है। CD कितना है?","optionsHi":["12 cm","9 cm","6 cm","15 cm"],"explanationHi":"PA × PB = PC × PD में PB = 4 + 5 = 9 रखने पर 36 = 3 × PD, अतः PD = 12 और CD = PD − PC = 12 − 3 = 9 cm। 12 cm, PD है, CD नहीं।","subtopic":"circles","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-195","question":"A chord of a circle subtends an angle of 40° at a point on the major arc. What angle does it subtend at a point on the minor arc?","options":["80°","140°","40°","100°"],"answer":1,"explanation":"The two points lie on opposite arcs, so the angles are the angles of a cyclic quadrilateral's opposite vertices and add up to 180°: 180° − 40° = 140°. (80° is the angle at the centre.)","difficulty":"hard","questionHi":"एक वृत्त की जीवा दीर्घ चाप के किसी बिंदु पर 40° का कोण बनाती है। लघु चाप के किसी बिंदु पर वह कितना कोण बनाएगी?","optionsHi":["80°","140°","40°","100°"],"explanationHi":"दोनों बिंदु विपरीत चापों पर हैं, इसलिए ये चक्रीय चतुर्भुज के सम्मुख कोणों के समान हैं और इनका योग 180° होता है: 180° − 40° = 140°। (80° केंद्र पर बना कोण है।)","subtopic":"circles","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-196","question":"If sin θ + cos θ = 7/5, what is the value of tan θ + cot θ?","options":["12/25","7/5","5/7","25/12"],"answer":3,"explanation":"Squaring, 1 + 2 sin θ cos θ = 49/25, so sin θ cos θ = 12/25. Then tan θ + cot θ = 1/(sin θ cos θ) = 25/12.","difficulty":"hard","questionHi":"यदि sin θ + cos θ = 7/5 है, तो tan θ + cot θ का मान क्या है?","optionsHi":["12/25","7/5","5/7","25/12"],"explanationHi":"वर्ग करने पर 1 + 2 sin θ cos θ = 49/25, अतः sin θ cos θ = 12/25। तब tan θ + cot θ = 1/(sin θ cos θ) = 25/12।","subtopic":"trigonometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-197","question":"What is the value of sin²15° + sin²25° + sin²35° + sin²45° + sin²55° + sin²65° + sin²75°?","options":["7/2","4","3","13/4"],"answer":0,"explanation":"Pair the complementary angles: sin²15° + sin²75° = 1, sin²25° + sin²65° = 1 and sin²35° + sin²55° = 1. Adding sin²45° = 1/2 gives 3 + 1/2 = 7/2.","difficulty":"hard","questionHi":"sin²15° + sin²25° + sin²35° + sin²45° + sin²55° + sin²65° + sin²75° का मान क्या है?","optionsHi":["7/2","4","3","13/4"],"explanationHi":"पूरक कोणों की जोड़ी बनाएँ: sin²15° + sin²75° = 1, sin²25° + sin²65° = 1 और sin²35° + sin²55° = 1। sin²45° = 1/2 जोड़ने पर 3 + 1/2 = 7/2।","subtopic":"trigonometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-198","question":"If sec θ + tan θ = 3 and θ is acute, what is sin θ?","options":["3/5","5/4","4/5","4/3"],"answer":2,"explanation":"Since sec²θ − tan²θ = 1, sec θ − tan θ = 1/3. Adding, 2 sec θ = 10/3, so sec θ = 5/3 and cos θ = 3/5. Then sin θ = 4/5.","difficulty":"moderate","questionHi":"यदि sec θ + tan θ = 3 है और θ न्यून कोण है, तो sin θ का मान क्या है?","optionsHi":["3/5","5/4","4/5","4/3"],"explanationHi":"चूँकि sec²θ − tan²θ = 1, sec θ − tan θ = 1/3। जोड़ने पर 2 sec θ = 10/3, अतः sec θ = 5/3 और cos θ = 3/5। तब sin θ = 4/5।","subtopic":"trigonometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-199","question":"If tan A = 1/2 and tan B = 1/3, with A and B acute, what is the value of tan(2A + B)?","options":["1","7","3","5/3"],"answer":2,"explanation":"tan 2A = 2(1/2)/(1 − 1/4) = 4/3. Then tan(2A + B) = (4/3 + 1/3)/(1 − 4/9) = (5/3)/(5/9) = 3. The value 1 is tan(A + B).","difficulty":"very-hard","questionHi":"यदि tan A = 1/2 और tan B = 1/3 है, जहाँ A और B न्यून कोण हैं, तो tan(2A + B) का मान क्या है?","optionsHi":["1","7","3","5/3"],"explanationHi":"tan 2A = 2(1/2)/(1 − 1/4) = 4/3। तब tan(2A + B) = (4/3 + 1/3)/(1 − 4/9) = (5/3)/(5/9) = 3। मान 1, tan(A + B) का है।","subtopic":"trigonometry","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-200","question":"In triangle ABC, AB = 6 cm, AC = 9 cm and BC = 10 cm. The bisector of ∠A meets BC at D. What is the length of AD?","options":["√30 cm","√24 cm","√54 cm","√20 cm"],"answer":0,"explanation":"By the angle bisector theorem BD : DC = 6 : 9, so BD = 4 and DC = 6. The bisector length satisfies AD² = AB × AC − BD × DC = 54 − 24 = 30, so AD = √30 cm.","difficulty":"very-hard","questionHi":"त्रिभुज ABC में AB = 6 cm, AC = 9 cm और BC = 10 cm है। ∠A का समद्विभाजक BC को D पर मिलता है। AD की लंबाई कितनी है?","optionsHi":["√30 cm","√24 cm","√54 cm","√20 cm"],"explanationHi":"कोण समद्विभाजक प्रमेय से BD : DC = 6 : 9, अतः BD = 4 और DC = 6। समद्विभाजक की लंबाई AD² = AB × AC − BD × DC = 54 − 24 = 30 को संतुष्ट करती है, अतः AD = √30 cm।","subtopic":"triangles-lines","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-201","question":"In an acute triangle ABC, ∠A = 70°. If I is the incentre and H is the orthocentre, what is ∠BIC + ∠BHC?","options":["265°","250°","215°","235°"],"answer":3,"explanation":"∠BIC = 90° + A/2 = 125° and ∠BHC = 180° − A = 110°, so the sum is 235°. (The circumcentre gives ∠BOC = 2A = 140°, which produces the other sums.)","difficulty":"hard","questionHi":"एक न्यून कोण त्रिभुज ABC में ∠A = 70° है। यदि I अंतःकेंद्र और H लंबकेंद्र है, तो ∠BIC + ∠BHC का मान क्या है?","optionsHi":["265°","250°","215°","235°"],"explanationHi":"∠BIC = 90° + A/2 = 125° और ∠BHC = 180° − A = 110°, अतः योग 235°। (परिकेंद्र से ∠BOC = 2A = 140° आता है, जिससे अन्य योग बनते हैं।)","subtopic":"triangles-lines","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-202","question":"The sides of a triangle are 13 cm, 14 cm and 15 cm. What is its circumradius?","options":["15/2 cm","65/8 cm","8 cm","7 cm"],"answer":1,"explanation":"Semi-perimeter 21, area = √(21 × 8 × 7 × 6) = 84 cm². Circumradius R = abc/(4 × area) = 2,730/336 = 65/8 cm. (The inradius would be 84/21 = 4.)","difficulty":"hard","questionHi":"एक त्रिभुज की भुजाएँ 13 cm, 14 cm और 15 cm हैं। उसकी परिवृत्त त्रिज्या कितनी है?","optionsHi":["15/2 cm","65/8 cm","8 cm","7 cm"],"explanationHi":"अर्धपरिमाप 21, क्षेत्रफल = √(21 × 8 × 7 × 6) = 84 cm²। परिवृत्त त्रिज्या R = abc/(4 × क्षेत्रफल) = 2,730/336 = 65/8 cm। (अंतःत्रिज्या 84/21 = 4 होती।)","subtopic":"triangles-lines","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-203","question":"If x + y + z = 6 and xy + yz + zx = 11, what is the value of x³ + y³ + z³ − 3xyz?","options":["36","18","66","6"],"answer":1,"explanation":"x² + y² + z² = 36 − 22 = 14. Then x³ + y³ + z³ − 3xyz = (x + y + z)(x² + y² + z² − xy − yz − zx) = 6 × (14 − 11) = 18.","difficulty":"hard","questionHi":"यदि x + y + z = 6 और xy + yz + zx = 11 है, तो x³ + y³ + z³ − 3xyz का मान क्या है?","optionsHi":["36","18","66","6"],"explanationHi":"x² + y² + z² = 36 − 22 = 14। तब x³ + y³ + z³ − 3xyz = (x + y + z)(x² + y² + z² − xy − yz − zx) = 6 × (14 − 11) = 18।","subtopic":"algebraic-identities","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-204","question":"If a − b = 3 and a³ − b³ = 117, what is the value of a² + b²?","options":["19","39","49","29"],"answer":3,"explanation":"a³ − b³ = (a − b)³ + 3ab(a − b) gives 117 = 27 + 9ab, so ab = 10. Then a² + b² = (a − b)² + 2ab = 9 + 20 = 29. (49 is (a + b)².)","difficulty":"hard","questionHi":"यदि a − b = 3 और a³ − b³ = 117 है, तो a² + b² का मान क्या है?","optionsHi":["19","39","49","29"],"explanationHi":"a³ − b³ = (a − b)³ + 3ab(a − b) से 117 = 27 + 9ab, अतः ab = 10। तब a² + b² = (a − b)² + 2ab = 9 + 20 = 29। (49, (a + b)² का मान है।)","subtopic":"algebraic-identities","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-205","question":"What is the value of (0.04)^(−3/2) × (0.125)^(2/3)?","options":["125/4","25/2","125/8","25/4"],"answer":0,"explanation":"(0.04)^(−3/2) = (1/25)^(−3/2) = 25^(3/2) = 125, and (0.125)^(2/3) = (1/8)^(2/3) = 1/4. The product is 125/4.","difficulty":"moderate","questionHi":"(0.04)^(−3/2) × (0.125)^(2/3) का मान क्या है?","optionsHi":["125/4","25/2","125/8","25/4"],"explanationHi":"(0.04)^(−3/2) = (1/25)^(−3/2) = 25^(3/2) = 125 और (0.125)^(2/3) = (1/8)^(2/3) = 1/4। गुणनफल 125/4 है।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-206","question":"If x = (1 + √5)/2, what is the value of x⁵?","options":["(7 + 3√5)/2","(9 + 4√5)/2","(11 + 5√5)/2","(13 + 5√5)/2"],"answer":2,"explanation":"x satisfies x² = x + 1. Then x³ = 2x + 1, x⁴ = 3x + 2 and x⁵ = 5x + 3 = 5(1 + √5)/2 + 3 = (11 + 5√5)/2. The value (7 + 3√5)/2 is x⁴.","difficulty":"very-hard","questionHi":"यदि x = (1 + √5)/2 है, तो x⁵ का मान क्या है?","optionsHi":["(7 + 3√5)/2","(9 + 4√5)/2","(11 + 5√5)/2","(13 + 5√5)/2"],"explanationHi":"x समीकरण x² = x + 1 को संतुष्ट करता है। तब x³ = 2x + 1, x⁴ = 3x + 2 और x⁵ = 5x + 3 = 5(1 + √5)/2 + 3 = (11 + 5√5)/2। मान (7 + 3√5)/2, x⁴ का है।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-207","question":"If 5^(x+1) = 125^(x−2), what is x?","options":["5/2","3","7/2","4"],"answer":2,"explanation":"125 = 5³, so 5^(x+1) = 5^(3x−6). Equal bases need equal exponents: x + 1 = 3x − 6, so x = 7/2.","difficulty":"moderate","questionHi":"यदि 5^(x+1) = 125^(x−2) है, तो x का मान क्या है?","optionsHi":["5/2","3","7/2","4"],"explanationHi":"125 = 5³, अतः 5^(x+1) = 5^(3x−6)। आधार बराबर होने पर घात बराबर होनी चाहिए: x + 1 = 3x − 6, अतः x = 7/2।","subtopic":"surds-indices","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
  {"id":"quant-algebra-geometry-208","question":"If a + b = 5 and ab = 3, what is the value of a⁴ + b⁴?","options":["343","361","325","307"],"answer":0,"explanation":"a² + b² = 25 − 6 = 19. Then a⁴ + b⁴ = (a² + b²)² − 2a²b² = 361 − 18 = 343. The value 361 forgets the −2a²b² term.","difficulty":"hard","questionHi":"यदि a + b = 5 और ab = 3 है, तो a⁴ + b⁴ का मान क्या है?","optionsHi":["343","361","325","307"],"explanationHi":"a² + b² = 25 − 6 = 19। तब a⁴ + b⁴ = (a² + b²)² − 2a²b² = 361 − 18 = 343। मान 361 में −2a²b² पद छूट गया है।","subtopic":"algebraic-identities","source":"SSC CGL Tier 2 · CAT · IBPS PO Mains"},
];

